import { Box } from '@mui/material'
import { DndContext, DragOverlay, PointerSensor, closestCorners, useSensor, useSensors } from '@dnd-kit/core'
import type { DragEndEvent, DragMoveEvent, DragStartEvent } from '@dnd-kit/core'
import { useCallback, useEffect, useRef, useState } from 'react'
import { buildCardColumns } from '../../data/card_ordering'
import type { CardTypeConfig, StateConfig } from '../../data/data_types'
import { useAgentAcknowledgements } from '../hooks/use_agent_acknowledgements'
import { dataService } from '../../services/data/data_service'
import { dialogService } from '../../services/dialog_service'
import { openFilesService } from '../../services/open_files_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { telemetryService } from '../../services/telemetry/telemetry_service'
import { AffectsEditorDialog } from './affects_editor_dialog'
import { CardActionPopupHost } from '../actions/card_action_popup_host'
import { CardBodyPopover } from './card_body_popover'
import { cardBodyPopoverService } from './card_body_popover_service'
import { CardColumn } from './card_column'
import { CardDragOverlay } from './card_drag_overlay'
import { cardDragDropService } from './card_drag_drop_service'
import { resolveCardDragEvent, type CardVerticalBounds } from './card_drag'
import { useCardViewColumns } from './use_card_view_columns'

const DRAG_ACTIVATION_DISTANCE = 2
interface CardViewProps {
    cardTypes: CardTypeConfig[]
    isMobile: boolean
    states: StateConfig[]
}

async function runCardEdit(action: () => unknown, fallbackMessage: string) {
    try {
        await action()
    } catch (error) {
        dialogService.error(error, { fallbackMessage })
    }
}

function measureCardVerticalBounds(): Map<string, CardVerticalBounds> {
    const boundsByPath = new Map<string, CardVerticalBounds>()
    const cardElements = document.querySelectorAll<HTMLElement>('[data-card-path]')
    for (const cardElement of cardElements) {
        const path = cardElement.dataset.cardPath
        if (!path) throw new Error('Card element is missing its path')

        const { height, top } = cardElement.getBoundingClientRect()
        boundsByPath.set(path, { height, top })
    }

    return boundsByPath
}

function currentCardColumns(states: StateConfig[]) {
    const cards = dataService.getState().snapshot?.activeCards ?? []

    return buildCardColumns(cards, states)
}

/** Card view: status columns of draggable cards with card-anchored body popup access. */
export function CardView(props: CardViewProps) {
    const {
        cardTypes,
        isMobile,
        states,
    } = props
    useAgentAcknowledgements()
    const columns = useCardViewColumns(states)
    const [openAffectsPath, setOpenAffectsPath] = useState<string | null>(null)
    const initialCardBoundsRef = useRef(new Map<string, CardVerticalBounds>())
    const rootElementRef = useRef<HTMLDivElement>(null)
    const missingRootReportedRef = useRef(false)
    const wasVisibleRef = useRef<boolean | null>(null)
    const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: DRAG_ACTIVATION_DISTANCE } }))

    const handleOpenAffects = (path: string) => {
        setOpenAffectsPath(path)
    }

    const handleCloseAffects = () => {
        setOpenAffectsPath(null)
    }

    const clearActiveCard = useCallback(() => {
        cardDragDropService.endDrag()
        initialCardBoundsRef.current.clear()
    }, [])

    useEffect(() => {
        const updateVisibility = () => {
            const rootElement = rootElementRef.current
            if (!rootElement) {
                if (!missingRootReportedRef.current) {
                    missingRootReportedRef.current = true
                    dialogService.error(new Error('Missing card view root element'), {fallbackMessage: 'Card view could not be displayed'})
                }
                return
            }

            const isVisible = workspaceViewService.getSnapshot().viewMode === 'cards'
            rootElement.style.display = isVisible ? 'flex' : 'none'
            if (wasVisibleRef.current === isVisible) return

            wasVisibleRef.current = isVisible
            if (isVisible) return

            queueMicrotask(() => {
                cardBodyPopoverService.close()
                setOpenAffectsPath((currentPath) => currentPath === null ? currentPath : null)
                clearActiveCard()
            })
        }

        updateVisibility()
        workspaceViewService.addEventListener('changed', updateVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateVisibility)
    }, [clearActiveCard])

    useEffect(() => () => cardBodyPopoverService.close(), [])

    const handleDragStart = useCallback((event: DragStartEvent) => {
        initialCardBoundsRef.current = measureCardVerticalBounds()
        cardDragDropService.startDrag(
            String(event.active.id),
            event.active.rect.current.initial?.height ?? null,
            event.active.rect.current.initial?.width ?? null,
        )
    }, [])

    const handleDragMove = useCallback((event: DragMoveEvent) => {
        const { active, over } = event
        if (!over) {
            cardDragDropService.setDropPreview(null)
            return
        }

        const dragColumns = currentCardColumns(states)
        const drop = resolveCardDragEvent(dragColumns, event, initialCardBoundsRef.current)
        const sourceColumn = dragColumns.find((column) => column.cards.some((card) => card.path === String(active.id)))
        const dropPreview = drop && sourceColumn?.status !== drop.targetStatus ? drop : null
        cardDragDropService.setDropPreview(dropPreview)
    }, [states])

    const handleDragEnd = useCallback((event: DragEndEvent) => {
        const { active, over } = event
        const drop = over ? resolveCardDragEvent(currentCardColumns(states), event, initialCardBoundsRef.current) : null
        clearActiveCard()
        const path = String(active.id)
        if (drop) void runCardEdit(() => dataService.cards.moveCard(path, drop.targetStatus, drop.targetIndex), `Card move failed: ${path}`)
    }, [clearActiveCard, states])

    const handleOpenInFileMode = (path: string) => {
        cardBodyPopoverService.close()
        workspaceViewService.selectPath(path)
        void runCardEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)
        workspaceViewService.setViewMode('text')
        telemetryService.trackEvent('navigation')
    }

    const handleDeleteCard = async (path: string) => {
        try {
            await dataService.cards.deleteCard(path)
            workspaceViewService.clearSelectedPath(path)
            cardBodyPopoverService.closePath(path)
            if (openAffectsPath === path) handleCloseAffects()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Card delete failed: ${path}` })
            throw error
        }
    }

    const handleTitleChange = (path: string, title: string) => {
        dataService.cards.updateCardTitle(path, title).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: `Title update failed: ${path}` })
        })
    }

    const handleTogglePolicy = (path: string, policyKey: string) => {
        void runCardEdit(() => dataService.cards.toggleCardPolicy(path, policyKey), `Policy toggle failed: ${path}`)
    }

    const handleAffectsChange = (path: string, affects: string[]) => {
        void runCardEdit(() => dataService.cards.updateCardAffects(path, affects), `Affects update failed: ${path}`)
    }

    return (
        <Box
            ref={rootElementRef}
            sx={{ bgcolor: 'background.default', display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}
        >
            <DndContext
                collisionDetection={closestCorners}
                onDragCancel={clearActiveCard}
                onDragEnd={handleDragEnd}
                onDragMove={handleDragMove}
                onDragStart={handleDragStart}
                sensors={sensors}
            >
                <Box
                    aria-label="Card columns"
                    sx={{
                        alignItems: 'flex-start',
                        display: 'flex',
                        flex: 1,
                        flexDirection: isMobile ? 'column' : 'row',
                        gap: 2,
                        height: '100%',
                        overflowX: isMobile ? 'hidden' : 'auto',
                        overflowY: 'auto',
                        p: 2.5,
                    }}
                >
                    {columns.map((column) => (
                        <CardColumn
                            key={column.status}
                            cardTypes={cardTypes}
                            column={column}
                            isMobile={isMobile}
                            onDeleteCard={handleDeleteCard}
                            onOpenInFileMode={handleOpenInFileMode}
                            onTitleChange={handleTitleChange}
                            onTogglePolicy={handleTogglePolicy}
                        />
                    ))}
                </Box>
                <DragOverlay>
                    <CardDragOverlay cardTypes={cardTypes} />
                </DragOverlay>
                <CardBodyPopover
                    isMobile={isMobile}
                    onDeleteCard={handleDeleteCard}
                    onOpenAffects={handleOpenAffects}
                    onOpenInFileMode={handleOpenInFileMode}
                    visible
                />
                <AffectsEditorDialog
                    cardPath={openAffectsPath}
                    onClose={handleCloseAffects}
                    onSave={handleAffectsChange}
                />
                <CardActionPopupHost />
            </DndContext>
        </Box>
    )
}

import { Box, Chip, IconButton, Paper, Tooltip, Typography } from '@mui/material'
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import Plus from 'mdi-material-ui/Plus'
import { useCallback, useSyncExternalStore } from 'react'
import type { ReactNode } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { requestOpenNewCardDialog } from '../project_command_events'
import { CardColumnDropTarget } from './card_column_drop_target'
import { cardDragDropService } from './card_drag_drop_service'
import { ProjectCardView, type CardHandlers } from './project_card_view'
import type { VisibleCardColumn } from './use_card_view_columns'
import { useCardColumnCards } from './use_card_column_cards'

const MIN_COLUMN_WIDTH = 200
const MAX_COLUMN_WIDTH = 320

interface CardColumnProps extends CardHandlers {
    cardTypes: CardTypeConfig[]
    column: VisibleCardColumn
    isMobile: boolean
}

/** One status column: a polished droppable stack with header metadata and an empty target. */
export function CardColumn(props: CardColumnProps) {
    const {
        cardTypes, column, isMobile,
        ...handlers
    } = props
    const cardPaths = useCardColumnCards(column.status)
    const subscribe = useCallback(
        (listener: () => void) => cardDragDropService.subscribeColumn(column.status, listener),
        [column.status],
    )
    const getSnapshot = useCallback(
        () => cardDragDropService.getColumnPreview(column.status),
        [column.status],
    )
    const dropPreview = useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
    const dropPreviewHeight = dropPreview?.dropPreviewHeight ?? null
    const dropPreviewIndex = dropPreview?.dropPreviewIndex ?? null
    const columnLabel = column.status || 'Unassigned'
    const dropPlaceholder = (
        <Box
            aria-label="Card drop position"
            key="drop-preview"
            sx={{
                bgcolor: 'action.selected',
                border: '1.5px dashed',
                borderColor: 'primary.main',
                borderRadius: 1.25,
                minHeight: dropPreviewHeight ?? 107,
            }}
        />
    )
    const cardElements: ReactNode[] = []
    for (let index = 0; index <= cardPaths.length; index += 1) {
        if (dropPreviewIndex === index) cardElements.push(dropPlaceholder)
        const cardPath = cardPaths[index]
        if (!cardPath) continue

        cardElements.push(
            <ProjectCardView
                key={cardPath}
                cardPath={cardPath}
                cardTypes={cardTypes}
                {...handlers}
            />,
        )
    }

    return (
        <Paper
            aria-label={`${columnLabel} column`}
            sx={{
                bgcolor: 'action.hover',
                borderRadius: 1.5,
                display: 'flex',
                flex: isMobile ? '0 0 auto' : 1,
                flexDirection: 'column',
                gap: 1,
                maxWidth: isMobile ? '100%' : MAX_COLUMN_WIDTH,
                minWidth: isMobile ? '100%' : MIN_COLUMN_WIDTH,
                p: 1,
            }}
        >
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1, minHeight: 34, pl: 1, pr: 0.5 }}>
                <Box sx={{ bgcolor: column.color, borderRadius: '3px', flexShrink: 0, height: 8, width: 8 }} />
                <Typography
                    component="h2"
                    sx={{ color: 'text.secondary', fontSize: 12, fontWeight: 700, letterSpacing: 0.6, textTransform: 'uppercase' }}
                >
                    {columnLabel}
                </Typography>
                <Chip
                    label={cardPaths.length}
                    size="small"
                    sx={{ bgcolor: 'background.paper', border: 1, borderColor: 'divider', fontSize: 11, height: 20 }}
                />
                <Box sx={{ flex: 1 }} />
                <Tooltip title="New card">
                    <IconButton aria-label={`Add card from ${columnLabel} column`} onClick={requestOpenNewCardDialog} size="small" sx={{ height: 26, width: 26 }}>
                        <Plus sx={{ fontSize: 16 }} />
                    </IconButton>
                </Tooltip>
            </Box>
            <SortableContext items={cardPaths} strategy={verticalListSortingStrategy}>
                <CardColumnDropTarget status={column.status}>
                    {cardElements}
                    {cardPaths.length === 0 && dropPreviewIndex === null ? (
                        <Box
                            sx={{
                                border: '1.5px dashed',
                                borderColor: 'divider',
                                borderRadius: 1.25,
                                color: 'text.disabled',
                                fontSize: 12,
                                p: 2,
                                textAlign: 'center',
                            }}
                        >
                            Drop a card here
                        </Box>
                    ) : null}
                </CardColumnDropTarget>
            </SortableContext>
        </Paper>
    )
}

import { Box } from '@mui/material'
import { useSortable } from '@dnd-kit/sortable'
import { useCallback } from 'react'
import type { MouseEventHandler, ReactNode, TouchEventHandler } from 'react'

export interface ProjectCardDragInteractions {
    onClick: MouseEventHandler<HTMLElement>
    onContextMenu: MouseEventHandler<HTMLElement>
    onTouchEnd: TouchEventHandler<HTMLElement>
    onTouchStart: TouchEventHandler<HTMLElement>
}

interface ProjectCardDragContainerProps {
    cardId: string
    cardPath: string
    children: ReactNode
    interactions: ProjectCardDragInteractions
    isBodyOpen: boolean
    isSelected: boolean
    onCardElementChange: (element: HTMLDivElement | null) => void
}

/** Lightweight sortable adapter that updates only card drag DOM around stable card content. */
export function ProjectCardDragContainer(props: ProjectCardDragContainerProps) {
    const {cardId, cardPath, children, interactions, isBodyOpen, isSelected, onCardElementChange} = props
    const { onClick, onContextMenu, onTouchEnd, onTouchStart } = interactions
    const sortable = useSortable({ id: cardPath })
    const { attributes, isDragging, listeners, setActivatorNodeRef, setNodeRef, transform, transition } = sortable
    const dragTranslation = transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : ''
    const transformStyle = `${dragTranslation}${isDragging ? ' rotate(2deg)' : ''}`.trim() || undefined
    const setCardElement = useCallback((element: HTMLDivElement | null) => {
        setNodeRef(element)
        onCardElementChange(element)
    }, [onCardElementChange, setNodeRef])

    return (
        <Box
            data-card-path={cardPath}
            data-selected={isSelected ? 'true' : undefined}
            onContextMenu={onContextMenu}
            onTouchCancel={onTouchEnd}
            onTouchEnd={onTouchEnd}
            onTouchMove={onTouchEnd}
            onTouchStart={onTouchStart}
            ref={setCardElement}
            sx={{
                bgcolor: 'background.paper',
                border: 1,
                borderColor: isSelected ? 'primary.main' : 'divider',
                borderRadius: 1.25,
                boxShadow: isDragging ? 'var(--md2-card-drag-shadow)' : 'var(--md2-card-shadow)',
                opacity: isDragging ? 0 : 1,
                overflow: 'hidden',
                position: 'relative',
                transform: transformStyle,
                transition,
                '&:hover': { borderColor: 'text.disabled', boxShadow: 'var(--md2-card-hover-shadow)' },
            }}
        >
            <Box
                {...attributes}
                {...listeners}
                aria-expanded={isBodyOpen}
                aria-haspopup="dialog"
                aria-label={`Drag ${cardId}`}
                component="button"
                onClick={onClick}
                ref={setActivatorNodeRef}
                sx={{
                    bgcolor: 'transparent',
                    border: 0,
                    cursor: isDragging ? 'grabbing' : 'pointer',
                    inset: 0,
                    position: 'absolute',
                    touchAction: 'none',
                    zIndex: 1,
                    '&:focus-visible': { outline: '2px solid', outlineColor: 'primary.main', outlineOffset: -2 },
                }}
                type="button"
            />
            {children}
        </Box>
    )
}

import type { CardColumn } from '../../data/card_ordering'
import type { CardTypeConfig } from '../../data/data_types'
import { getCardIdPrefix } from '../../data/card_identifiers'
import type { DragEndEvent, DragMoveEvent } from '@dnd-kit/core'

/** Droppable ids for empty/append targets are the status prefixed with this. */
export const COLUMN_DROP_PREFIX = 'column:'

/** Build the droppable id for a status column. */
export function columnDropId(status: string) {
    return `${COLUMN_DROP_PREFIX}${status}`
}

export interface DropTarget {
    targetIndex: number
    targetStatus: string
}

export type CardDropPlacement = 'after' | 'before'

export interface CardVerticalBounds {
    height: number
    top: number
}

type CardDragPositionEvent = DragEndEvent | DragMoveEvent

function getPointerY(event: CardDragPositionEvent): number {
    const { activatorEvent, delta } = event
    if (!('clientY' in activatorEvent) || typeof activatorEvent.clientY !== 'number') {
        throw new Error('Card dragging requires a pointer event with a vertical position')
    }

    return activatorEvent.clientY + delta.y
}

/** Resolve whether the pointer targets the half before or after a hovered card. */
export function getCardDropPlacement(pointerY: number, cardTop: number, cardHeight: number): CardDropPlacement {
    const cardMiddleY = cardTop + cardHeight / 2

    return pointerY < cardMiddleY ? 'before' : 'after'
}

/** Resolve a DnD event using stable drag-start bounds when available and current collision bounds otherwise. */
export function resolveCardDragEvent(
    columns: CardColumn[],
    event: CardDragPositionEvent,
    initialCardBounds: Map<string, CardVerticalBounds>,
): DropTarget | null {
    const { active, over } = event
    if (!over) return null

    const overId = String(over.id)
    const cardBounds = initialCardBounds.get(overId)
    const cardTop = cardBounds?.top ?? over.rect.top
    const cardHeight = cardBounds?.height ?? over.rect.height
    const pointerY = getPointerY(event)
    const cardDropPlacement = getCardDropPlacement(pointerY, cardTop, cardHeight)

    return resolveDrop(columns, String(active.id), overId, cardDropPlacement)
}

/**
 * Translate a drag end (active card path, the id it was dropped over) into the
 * target status and the insert index within the destination column's cards
 * excluding the dragged card. Returns null for a drop that changes nothing.
 */
export function resolveDrop(
    columns: CardColumn[],
    activePath: string,
    overId: string,
    cardDropPlacement: CardDropPlacement,
): DropTarget | null {
    if (activePath === overId) return null

    if (overId.startsWith(COLUMN_DROP_PREFIX)) {
        const status = overId.slice(COLUMN_DROP_PREFIX.length)
        const column = columns.find((entry) => entry.status === status)
        if (!column) return null

        const remaining = column.cards.filter((card) => card.path !== activePath)

        return { targetIndex: remaining.length, targetStatus: status }
    }

    const targetColumn = columns.find((entry) => entry.cards.some((card) => card.path === overId))
    if (!targetColumn) return null

    const remaining = targetColumn.cards.filter((card) => card.path !== activePath)
    const overIndex = remaining.findIndex((card) => card.path === overId)
    const targetIndex = overIndex === -1 ? remaining.length : overIndex + (cardDropPlacement === 'after' ? 1 : 0)

    return { targetIndex, targetStatus: targetColumn.status }
}

/** Resolve the configured type color for a card id via its prefix (e.g. `F-005` â†’ `F`). */
export function getCardTypeColor(cardTypes: CardTypeConfig[], id: string): string | undefined {
    const prefix = getCardIdPrefix(id)

    return cardTypes.find((cardType) => cardType.idPrefix === prefix)?.color
}

import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react'
import { DndContext } from '@dnd-kit/core'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { CardView } from './card_view'
import { CardColumn } from './card_column'
import * as cardColumnModule from './card_column'
import { actionService } from '../../services/actions/action_service'
import type { ActionFile } from '../../data/action_types'
import { DEFAULT_CARD_TYPES, type CardTypeConfig, type ProjectCard } from '../../data/data_types'
import { telemetryService } from '../../services/telemetry/telemetry_service'
import { AppThemeProvider } from '../../theme/theme_provider'
import { dataService } from '../../services/data/data_service'
import { worktreeService } from '../../services/project/worktree_service'
import { cardMarkdownDataSource } from '../editor/card_markdown_data_source'
import { openFilesService } from '../../services/open_files_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { cardDragDropService } from './card_drag_drop_service'

function card(id: string, title: string, status: string, policy: Record<string, boolean> = {}): ProjectCard {
    return {
        agentConversationErrors: [],
        agentConversations: [],
        headerFields: {},
        content: `# ${title}\n\nBody of ${id}`,
        header: {
            affects: [], after: null, agentLogReferences: [], author: null, id, internalId: id.toLowerCase(), owner: null,
            policy, status, title,
            worktree: null, worktreeError: null, worktreeValue: null,
        },
        isActive: true,
        path: `design/${id}.md`,
    }
}

const cards = [
    card('F-1', 'First', 'todo', { checkLinting: true, requireTests: false }),
    card('F-2', 'Second', 'done'),
]

function setProjectCards(activeCards: ProjectCard[], repositoryFiles = ['app/src/app.tsx', 'design/F-1.md']) {
    vi.mocked(dataService.getState).mockReturnValue({
        project: { branch: 'main', id: 'project', rootPath: 'C:\\project' },
        runningAgents: [],
        snapshot: { activeCards, backgroundCards: [], repositoryFiles, workingFolder: 'design' },
    })
}

function actionFile(definition: unknown): ActionFile {
    return { content: JSON.stringify(definition), path: 'actions/action.json' }
}

function createColumnHandlers() {
    return {
        onDeleteCard: vi.fn(async () => undefined),
        onOpenInFileMode: vi.fn(),
        onTitleChange: vi.fn(),
        onTogglePolicy: vi.fn(),
    }
}

function renderCardView(
    overrides: Partial<Parameters<typeof CardView>[0]> = {},
    activeCards = cards,
    repositoryFiles = ['app/src/app.tsx', 'design/F-1.md'],
) {
    setProjectCards(activeCards, repositoryFiles)

    render(
        <AppThemeProvider>
            <CardView
                cardTypes={DEFAULT_CARD_TYPES}
                isMobile={false}
                states={[
                    { alwaysVisible: false, state: 'todo' },
                    { alwaysVisible: false, state: 'done' },
                ]}
                {...overrides}
            />
        </AppThemeProvider>,
    )
}

describe('CardView', () => {
    beforeEach(() => {
        workspaceViewService.setViewMode('cards')
        cardDragDropService.endDrag()
        vi.spyOn(dataService, 'getState')
        setProjectCards(cards)
        vi.spyOn(dataService.cards, 'deleteCard').mockResolvedValue(null)
        vi.spyOn(dataService.cards, 'moveCard').mockResolvedValue([])
        vi.spyOn(dataService.cards, 'toggleCardPolicy').mockReturnValue(cards[0])
        vi.spyOn(dataService.cards, 'updateCardAffects').mockReturnValue(cards[0])
        vi.spyOn(dataService.cards, 'updateCardTitle').mockResolvedValue(cards[0])
        vi.spyOn(openFilesService, 'openPath')
        vi.spyOn(dataService, 'hasPendingFile').mockReturnValue(false)
        vi.spyOn(cardMarkdownDataSource, 'getMarkdown').mockImplementation((target) => target.document.kind === 'card'
            ? target.document.getDraft().content
            : '')
        vi.spyOn(cardMarkdownDataSource, 'commit').mockReturnValue(true)
        vi.spyOn(cardMarkdownDataSource, 'updateActiveCardTitle').mockImplementation(() => undefined)
    })

    afterEach(() => {
        cleanup()
        cardDragDropService.endDrag()
        const { selectedPath } = workspaceViewService.getSnapshot()
        if (selectedPath) workspaceViewService.clearSelectedPath(selectedPath)
        for (const document of openFilesService.getRegisteredDocuments()) openFilesService.discardDocument(document)
        actionService.clear()
        vi.restoreAllMocks()
    })

    it('keeps hidden card columns mounted without occupying layout', () => {
        workspaceViewService.setViewMode('text')
        renderCardView()

        const cardColumns = screen.getByLabelText('Card columns')

        expect(cardColumns).not.toBeVisible()
        expect(cardColumns.parentElement).toHaveStyle({ display: 'none' })
    })

    it('switches visibility without rerendering card columns', () => {
        const renderCardColumn = vi.spyOn(cardColumnModule, 'CardColumn')
        renderCardView()
        const cardColumns = screen.getByLabelText('Card columns')
        renderCardColumn.mockClear()

        act(() => workspaceViewService.setViewMode('text'))
        act(() => workspaceViewService.setViewMode('cards'))

        expect(screen.getByLabelText('Card columns')).toBe(cardColumns)
        expect(renderCardColumn).not.toHaveBeenCalled()
    })

    it('groups cards into a column per status with id and title', () => {
        renderCardView()

        expect(screen.getByText('todo')).toBeInTheDocument()
        expect(screen.getByText('done')).toBeInTheDocument()
        expect(screen.getByText('F-1')).toBeInTheDocument()
        expect(screen.getByText('First')).toBeInTheDocument()
    })

    it('lets desktop columns flex between their minimum and maximum widths', () => {
        renderCardView()

        const columnStyle = window.getComputedStyle(screen.getByLabelText('todo column'))

        expect(columnStyle.flexGrow).toBe('1')
        expect(columnStyle.minWidth).toBe('200px')
        expect(columnStyle.maxWidth).toBe('320px')
    })

