import { Box, IconButton, Menu, MenuItem, Stack, TextField, Tooltip, Typography, useTheme } from '@mui/material'
import { alpha } from '@mui/material/styles'
import DotsVertical from 'mdi-material-ui/DotsVertical'
import FileDocumentOutline from 'mdi-material-ui/FileDocumentOutline'
import { useState, useSyncExternalStore } from 'react'
import type { ChangeEvent, KeyboardEvent, MouseEvent, TouchEvent } from 'react'
import type { CardTypeConfig, ProjectCard } from '../../data/data_types'
import { cardContext } from '../../data/action_context'
import { telemetryService } from '../../services/telemetry/telemetry_service'
import { dialogService } from '../../services/dialog_service'
import { ActionEntryPoints } from '../actions/action_entry_points'
import { CardRunButton } from '../actions/card_run_button'
import { useRunningActionForFile } from '../hooks/use_action_executions'
import { CardDeleteDialog } from './card_delete_dialog'
import { CardPolicyMenuItem } from './card_policy_menu_item'
import { CardWorktreeIndicator } from './card_worktree_indicator'
import { getCardTypeColor } from './card_drag'
import { useProjectCard } from './use_project_card'
import { useProjectReference } from '../hooks/use_project_reference'
import { useIsWorkspacePathSelected } from '../hooks/use_is_workspace_path_selected'
import { cardBodyPopoverService, subscribeCardBodyPopover } from './card_body_popover_service'
import { ProjectCardDragContainer } from './project_card_drag_container'

const CARD_LONG_PRESS_MS = 500

export interface CardHandlers {
    onDeleteCard: (path: string) => Promise<void>
    onOpenInFileMode: (path: string) => void
    onTogglePolicy: (path: string, policyKey: string) => void
    onTitleChange: (path: string, title: string) => void
}

interface ProjectCardViewProps extends CardHandlers {
    cardPath: string
    cardTypes: CardTypeConfig[]
}

interface ProjectCardViewContentProps extends CardHandlers {
    card: ProjectCard
    cardTypes: CardTypeConfig[]
    isSelected: boolean
    primaryPath: string
    projectKey: string
}

interface MenuPosition {
    left: number
    top: number
}

/** A three-row draggable card with compact metadata and consolidated actions. */
export function ProjectCardView(props: ProjectCardViewProps) {
    const { cardPath, ...contentProps } = props
    const card = useProjectCard(cardPath)
    const project = useProjectReference()
    const isSelected = useIsWorkspacePathSelected(cardPath)
    if (!card || !project) return null

    const primaryPath = project.rootPath ?? project.id
    const projectKey = `${project.id}:${project.branch}`

    return (
        <ProjectCardViewContent
            card={card}
            isSelected={isSelected}
            primaryPath={primaryPath}
            projectKey={projectKey}
            {...contentProps}
        />
    )
}

function ProjectCardViewContent(props: ProjectCardViewContentProps) {
    const { card, cardTypes, isSelected, primaryPath, projectKey } = props
    const { onOpenInFileMode } = props
    const { onDeleteCard, onTogglePolicy, onTitleChange } = props
    const theme = useTheme()
    const [cardElement, setCardElement] = useState<HTMLDivElement | null>(null)
    const [actionsAnchorElement, setActionsAnchorElement] = useState<HTMLElement | null>(null)
    const [actionsMenuPosition, setActionsMenuPosition] = useState<MenuPosition | null>(null)
    const [isEditingTitle, setIsEditingTitle] = useState(false)
    const [deleteCardPath, setDeleteCardPath] = useState<string | null>(null)
    const [longPressTimer, setLongPressTimer] = useState<number | null>(null)
    const [titleDraft, setTitleDraft] = useState(card.header.title)
    const isBodyOpen = useSyncExternalStore(
        subscribeCardBodyPopover,
        () => cardBodyPopoverService.getSnapshot().cardPath === card.path,
        () => false,
    )
    const accentColor = getCardTypeColor(cardTypes, card.header.id) ?? theme.palette.primary.main
    const accentBackground = alpha(accentColor, 0.16)
    const runningExecution = useRunningActionForFile(card.path)
    const statusLabel = runningExecution ? 'Running' : 'Idle'

    const commitTitle = () => {
        setIsEditingTitle(false)
        const nextTitle = titleDraft.trim()
        if (nextTitle.length > 0 && nextTitle !== card.header.title) onTitleChange(card.path, nextTitle)
    }

    const handleTitleKeyDown = (event: KeyboardEvent) => {
        if (event.key === 'Enter') commitTitle()
        if (event.key === 'Escape') setIsEditingTitle(false)
    }

    const handleTitleDraftChange = (event: ChangeEvent<HTMLInputElement>) => {
        setTitleDraft(event.target.value)
    }

    const handleCardClick = (event: MouseEvent<HTMLElement>) => {
        if (isEditingTitle) return

        cardBodyPopoverService.toggle(card.path, event.currentTarget)
        telemetryService.trackEvent('navigation')
    }

    const stopClick = (event: MouseEvent) => {
        event.stopPropagation()
    }

    const openCardActions = (event: MouseEvent<HTMLElement>) => {
        event.stopPropagation()
        setActionsMenuPosition(null)
        setActionsAnchorElement(event.currentTarget)
    }

    const openCardContextMenu = (event: MouseEvent<HTMLElement>) => {
        event.preventDefault()
        event.stopPropagation()
        setActionsAnchorElement(null)
        setActionsMenuPosition({ left: event.clientX, top: event.clientY })
    }

    const openInFileMode = (event: MouseEvent<HTMLElement>) => {
        event.stopPropagation()
        onOpenInFileMode(card.path)
    }

    const closeCardActions = () => {
        setActionsAnchorElement(null)
        setActionsMenuPosition(null)
    }

    const openBodyFromMenu = () => {
        try {
            if (!cardElement) throw new Error(`Missing card element: ${card.path}`)
            closeCardActions()
            cardBodyPopoverService.toggle(card.path, cardElement)
            telemetryService.trackEvent('navigation')
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Card details could not be opened' })
        }
    }

    const openInFileModeFromMenu = () => {
        closeCardActions()
        onOpenInFileMode(card.path)
    }

    const editTitleFromMenu = () => {
        closeCardActions()
        setTitleDraft(card.header.title)
        setIsEditingTitle(true)
    }

    const clearLongPressTimer = () => {
        if (longPressTimer !== null) window.clearTimeout(longPressTimer)
        setLongPressTimer(null)
    }

    const handleCardTouchStart = (event: TouchEvent<HTMLElement>) => {
        if (event.touches.length !== 1) return

        const { clientX, clientY } = event.touches[0]
        const timer = window.setTimeout(() => {
            setActionsAnchorElement(null)
            setActionsMenuPosition({ left: clientX, top: clientY })
        }, CARD_LONG_PRESS_MS)
        setLongPressTimer(timer)
    }

    const handleCardTouchEnd = () => {
        clearLongPressTimer()
    }

    const closeDeleteCardDialog = () => {
        setDeleteCardPath(null)
    }

    const openDeleteCardDialog = () => {
        closeCardActions()
        setDeleteCardPath(card.path)
    }

    const policyKeys = Object.keys(card.header.policy)
    const dragInteractions = {
        onClick: handleCardClick,
        onContextMenu: openCardContextMenu,
        onTouchEnd: handleCardTouchEnd,
        onTouchStart: handleCardTouchStart,
    }

    return (
        <ProjectCardDragContainer
            cardId={card.header.id}
            cardPath={card.path}
            interactions={dragInteractions}
            isBodyOpen={isBodyOpen}
            isSelected={isSelected}
            onCardElementChange={setCardElement}
        >
            <Box sx={{ bgcolor: accentColor, bottom: 0, left: 0, position: 'absolute', top: 0, width: 4 }} />
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, minWidth: 0, p: '10px 12px 10px 14px', pointerEvents: 'none' }}>
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', minHeight: 24, position: 'relative', zIndex: 2 }}>
                    <Box
                        component="span"
                        sx={{
                            bgcolor: accentBackground,
                            borderRadius: '5px',
                            color: accentColor,
                            fontFamily: '"Roboto Mono", ui-monospace, monospace',
                            fontSize: 11.5,
                            fontWeight: 600,
                            px: 0.875,
                            py: 0.25,
                        }}
                    >
                        {card.header.id}
                    </Box>
                    <Box component="span" sx={{ alignItems: 'center', color: 'text.secondary', display: 'flex', fontSize: 11, gap: 0.625 }}>
                        <Box sx={{ bgcolor: runningExecution ? 'success.main' : 'text.disabled', borderRadius: '50%', height: 7, width: 7 }} />
                        {statusLabel}
                    </Box>
                    <Box sx={{ flex: 1 }} />
                    <Tooltip title="Card actions">
                        <IconButton
                            aria-label={`Card actions for ${card.header.id}`}
                            onClick={openCardActions}
                            size="small"
                            sx={{ color: 'text.disabled', height: 24, pointerEvents: 'auto', width: 24 }}
                        >
                            <DotsVertical sx={{ fontSize: 16 }} />
                        </IconButton>
                    </Tooltip>
                </Stack>
                {isEditingTitle ? (
                    <Box sx={{ pointerEvents: 'auto', position: 'relative', zIndex: 2 }}>
                        <TextField
                            autoFocus
                            fullWidth
                            onBlur={commitTitle}
                            onChange={handleTitleDraftChange}
                            onClick={stopClick}
                            onKeyDown={handleTitleKeyDown}
                            size="small"
                            value={titleDraft}
                        />
                    </Box>
                ) : (
                    <Typography sx={{ color: 'text.primary', fontSize: 13.5, fontWeight: 500, lineHeight: 1.4 }}>
                        {card.header.title}
                    </Typography>
                )}
                <Stack direction="row" spacing={0.75} sx={{ alignItems: 'center', minHeight: 26, position: 'relative', zIndex: 2 }}>
                    <Box sx={{ pointerEvents: 'auto' }}>
                        <CardRunButton
                            card={card}
                            context={cardContext(card, cardTypes)}
                            projectKey={projectKey}
                        />
                    </Box>
                    <Tooltip title="Open in file mode">
                        <IconButton
                            aria-label={`Open ${card.header.id} in file mode`}
                            onClick={openInFileMode}
                            size="small"
                            sx={{ border: 1, borderColor: 'divider', borderRadius: '50%', height: 26, pointerEvents: 'auto', width: 26 }}
                        >
                            <FileDocumentOutline sx={{ fontSize: 14 }} />
                        </IconButton>
                    </Tooltip>
                    <Box sx={{ flex: 1 }} />
                    <CardWorktreeIndicator
                        card={card}
                        primaryPath={primaryPath}
                    />
                </Stack>
            </Box>
            <Menu
                anchorEl={actionsAnchorElement}
                anchorPosition={actionsMenuPosition ?? undefined}
                anchorReference={actionsMenuPosition ? 'anchorPosition' : 'anchorEl'}
                onClose={closeCardActions}
                open={!!actionsAnchorElement || !!actionsMenuPosition}
            >
                <ActionEntryPoints
                    context={cardContext(card, cardTypes)}
                    onMenuItemSelected={closeCardActions}
                    popupAnchorElement={cardElement}
                    variant="menuItems"
                />
                {policyKeys.map((policyKey) => (
                    <CardPolicyMenuItem
                        key={policyKey}
                        cardPath={card.path}
                        enabled={card.header.policy[policyKey] ?? false}
                        onSelected={closeCardActions}
                        onToggle={onTogglePolicy}
                        policyKey={policyKey}
                    />
                ))}
                <MenuItem onClick={openBodyFromMenu}>Open body</MenuItem>
                <MenuItem onClick={openInFileModeFromMenu}>Open in file mode</MenuItem>
                <MenuItem onClick={editTitleFromMenu}>Edit title</MenuItem>
                <MenuItem onClick={openDeleteCardDialog}>Delete</MenuItem>
            </Menu>
            <CardDeleteDialog cardPath={deleteCardPath} onClose={closeDeleteCardDialog} onDeleteCard={onDeleteCard} />
        </ProjectCardDragContainer>
    )
}

import { Box, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'
import { useCallback, useEffect, useMemo, useRef } from 'react'
import type { UseGithubAuthResult } from '../auth/use_github_auth'
import {
    DEFAULT_CARD_TYPES,
    DEFAULT_ACTIONS_FOLDER,
    DEFAULT_ARCHIVED_FOLDER,
    DEFAULT_PROJECT_FOLDER,
    DEFAULT_RELEASES_FOLDER,
    DEFAULT_STATES,
    defaultColumnAccent,
} from '../data/data_types'
import { dataService } from '../services/data/data_service'
import { dialogService } from '../services/dialog_service'
import { getElectronLifecycleBridge, type ElectronLifecycleBridge } from '../services/electron_lifecycle_bridge'
import { openFilesService } from '../services/open_files_service'
import type { OpenDocument } from '../services/open_files_service'
import { telemetryService } from '../services/telemetry/telemetry_service'
import { workspaceViewService } from '../services/project/workspace_view_service'
import { workspaceNavigationService, type WorkspaceOpenRequest } from '../services/project/workspace_navigation_service'
import { projectPersistenceService } from '../services/project/project_persistence_service'
import { CardView } from './card_view/card_view'
import { flushMarkdownEditors } from './editor/markdown_editor_flush'
import { useProjectReference } from './hooks/use_project_reference'
import { TextView } from './text_view/text_view'
import { FileTreeView } from './text_view/file_tree_view'
import { useProjectConfig } from './hooks/use_project_config'
import { useWorkingFolder } from './hooks/use_working_folder'
import { ProjectWorkspaceAvailability } from './project_workspace_availability'
import { MobileLayout } from './shell/mobile_layout'
import { MobileMainWindow } from './shell/mobile_main_window'
import { SplitLayout } from './shell/split_layout'

const WORKSPACE_PANEL_PADDING = 3

function openDocumentPath(document: OpenDocument) {
    return document.kind === 'card' ? document.getObject().path : document.getObject().sourcePath
}

function flushPendingCommits() {
    flushMarkdownEditors()
    void projectPersistenceService.flushPendingChanges().catch((error: unknown) => {
        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved' })
    })
}

async function flushAndConfirmPendingCommits(lifecycleBridge: ElectronLifecycleBridge, requestId: string) {
    try {
        flushMarkdownEditors()
        await projectPersistenceService.flushPendingChanges()
        lifecycleBridge.confirmFlush(requestId)
    } catch (error) {
        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved before closing' })
    }
}

function runWorkspaceEdit(action: () => void, fallbackMessage: string) {
    try {
        action()
    } catch (error) {
        dialogService.error(error, { fallbackMessage })
    }
}

interface ProjectWorkspaceProps {
    auth: UseGithubAuthResult
    isMenuOpen: boolean
    onLeftPanelInteraction: () => void
}

export function ProjectWorkspace(props: ProjectWorkspaceProps) {
    const { auth, isMenuOpen, onLeftPanelInteraction } = props
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const project = useProjectReference()
    const projectConfig = useProjectConfig()
    const workingFolder = useWorkingFolder()
    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES
    const states = projectConfig?.states ?? DEFAULT_STATES
    const projectFolder = projectConfig?.projectFolder ?? DEFAULT_PROJECT_FOLDER
    const actionsFolder = projectConfig?.actionsFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ACTIONS_FOLDER}`
    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`
    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`
    const onLeftPanelInteractionRef = useRef(onLeftPanelInteraction)
    const statusColors = useMemo(() => new Map(
        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),
    ), [states])

    useEffect(() => {
        onLeftPanelInteractionRef.current = onLeftPanelInteraction
    })

    const handleCreateFolder = useCallback(async (parentDirectory: string, name: string) => {
        await dataService.cards.createFolder(parentDirectory, name)
    }, [])

    const handleCreateMarkdownFile = useCallback(async (parentDirectory: string, name: string) => {
        await dataService.cards.createMarkdownFile(parentDirectory, name)
    }, [])

    const handleDeleteFile = useCallback(async (path: string) => {
        try {
            await dataService.cards.deleteFile(path)
            const document = openFilesService.getSnapshot().documents.find((candidate) => openDocumentPath(candidate) === path)
            if (document) openFilesService.closeDocument(document)
            workspaceViewService.clearSelectedPath(path)
            onLeftPanelInteractionRef.current()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `File delete failed: ${path}` })
            throw error
        }
    }, [])

    const handleDeleteFolder = useCallback(async (path: string) => {
        try {
            await dataService.cards.deleteFolder(path)
            const folderPrefix = `${path.replace(/\/+$/u, '')}/`
            const documents = openFilesService.getSnapshot().documents
            for (const document of documents) {
                const openPath = openDocumentPath(document)
                if (openPath?.startsWith(folderPrefix)) openFilesService.closeDocument(document)
            }
            const selectedPath = workspaceViewService.getSnapshot().selectedPath
            if (selectedPath?.startsWith(folderPrefix)) workspaceViewService.clearSelectedPath(selectedPath)
            onLeftPanelInteractionRef.current()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Folder deletion failed: ${path}` })
            throw error
        }
    }, [])

    useEffect(() => {
        const handleBeforeUnload = (event: BeforeUnloadEvent) => {
            flushMarkdownEditors()
            const { hasPendingPush, hasPendingSave } = projectPersistenceService.getSnapshot()
            // In Electron, vetoing beforeunload silently cancels the window close (no confirm
            // dialog), leaving the app unclosable. The main process flushes pending commits on
            // quit instead, so only prompt in a plain browser build.
            if ((hasPendingPush || hasPendingSave) && !getElectronLifecycleBridge()) {
                event.preventDefault()
                event.returnValue = ''
            }

            flushPendingCommits()
        }

        const handleVisibilityChange = () => {
            if (document.visibilityState === 'hidden') flushPendingCommits()
        }

        const handleBlur = () => {
            flushMarkdownEditors()
            if (projectPersistenceService.getSnapshot().hasPendingSave) flushPendingCommits()
        }

        document.addEventListener('visibilitychange', handleVisibilityChange)
        window.addEventListener('beforeunload', handleBeforeUnload)
        window.addEventListener('blur', handleBlur)

        return () => {
            document.removeEventListener('visibilitychange', handleVisibilityChange)
            window.removeEventListener('beforeunload', handleBeforeUnload)
            window.removeEventListener('blur', handleBlur)
        }
    }, [])

    useEffect(() => {
        const lifecycleBridge = getElectronLifecycleBridge()
        if (!lifecycleBridge) return undefined

        return lifecycleBridge.onFlushRequested((requestId) => {
            void flushAndConfirmPendingCommits(lifecycleBridge, requestId)
        })
    }, [])

    useEffect(() => {
        const handleNavigationOpen = (event: Event) => {
            const { path } = (event as CustomEvent<WorkspaceOpenRequest>).detail
            // Reveal the card/file without changing the current view mode: highlight it in card view
            // and open it in the service-owned text-view tabs.
            workspaceViewService.selectPath(path)
            runWorkspaceEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)
            telemetryService.trackEvent('navigation')
        }

        workspaceNavigationService.addEventListener('open', handleNavigationOpen)

        return () => workspaceNavigationService.removeEventListener('open', handleNavigationOpen)
    }, [])

    const fileTree = (
        <Box
            aria-label="File tree"
            sx={{ bgcolor: 'action.hover', display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}
        >
            <FileTreeView
                actionsFolder={actionsFolder}
                archivedFolder={archivedFolder}
                cardTypes={cardTypes}
                onCreateFolder={handleCreateFolder}
                onCreateMarkdownFile={handleCreateMarkdownFile}
                onDeleteFile={handleDeleteFile}
                onDeleteFolder={handleDeleteFolder}
                onLeftPanelInteraction={onLeftPanelInteraction}
                projectFolder={projectFolder}
                releasesFolder={releasesFolder}
                statusColors={statusColors}
                workingFolder={workingFolder}
            />
        </Box>
    )
    const textView = (
        <Paper
            elevation={0}
            sx={{
                border: 1,
                borderColor: 'divider',
                borderRadius: 2,
                boxSizing: 'border-box',
                display: 'flex',
                height: '100%',
                minHeight: 0,
                overflow: 'hidden',
                p: WORKSPACE_PANEL_PADDING,
            }}
        >
            <TextView
                actionsFolder={actionsFolder}
                archivedFolder={archivedFolder}
                cardTypes={cardTypes}
                projectFolder={projectFolder}
                releasesFolder={releasesFolder}
                states={states}
            />
        </Paper>
    )
    const views = (
        <>
            {isMobile ? <MobileLayout content={textView} /> : <SplitLayout left={fileTree} right={textView} />}
            <CardView cardTypes={cardTypes} isMobile={isMobile} states={states} />
        </>
    )
    const workspace = (
        <ProjectWorkspaceAvailability>
            {views}
        </ProjectWorkspaceAvailability>
    )
    const navigation = project ? fileTree : (
        <Box sx={{ p: 2 }}>
            <Typography color="text.secondary" variant="body2">
                No project navigation available.
            </Typography>
        </Box>
    )

    return (
        <Box
            aria-label="Project workspace"
            component="section"
            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}
        >
            {isMobile ? (
                <MobileMainWindow
                    auth={auth}
                    isMenuOpen={isMenuOpen}
                    leftPanel={navigation}
                    onCloseMenu={onLeftPanelInteraction}
                    rightPanel={workspace}
                    showNavigationInCards={!project}
                />
            ) : workspace}
        </Box>
    )
}

