p.agent')\n    const selectedProfile = findAgentProfile(agentProfiles, selectedAgent)\n    const selectedModels = selectedProfile?.models ?? []\n    const configuredModel = useConfigValue('desktop.model')\n    const selectedThinkingLevel = useConfigValue('desktop.thinkingLevel')\n    const desktopAvailable = useHasDesktopConfig()\n    const selectedModel = configuredModel || (selectedProfile ? defaultModelForProfile(selectedProfile) : '')\n    const projectBranch = project?.branch ?? ''\n\n    const closeDialog = useCallback(() => {\n        setDialogMode(null)\n    }, [])\n\n    const openDialog = useCallback((mode: ProjectDialogMode) => {\n        setDialogMode(mode)\n    }, [])\n\n    const actions = useProjectToolbarMenuActions({\n        accessToken,\n        isGithubAuthenticated,\n        onCloseDialog: closeDialog,\n        onOpenDialog: openDialog,\n    })\n    const branchOptions = actions.branches.length > 0 ? actions.branches : (project ? [{ name: project.branch }] : [])\n    const selectedBranch = branchOptions.some((branch) => branch.name === actions.switchBranch) ? actions.switchBranch : projectBranch\n\n    const handleTabChange = (_event: SyntheticEvent, value: AppMenuTab) => {\n        setCurrentTab(value)\n    }\n\n    const handleOpenProject = () => {\n        actions.openProjectDialog()\n    }\n\n    const handleCreateProjectFolders = (projectFolder: string) => {\n        void actions.createProjectFolders(projectFolder)\n    }\n\n    const handleLoadBranches = () => {\n        void actions.loadSwitchBranches()\n    }\n\n    const handleBranchChange = (event: SelectChangeEvent) => {\n        void actions.switchProjectBranch(event.target.value)\n    }\n\n    const handleOpenReleaseDialog = () => {\n        openDialog('release')\n    }\n\n    const handleOpenCardDialog = () => {\n        openDialog('card')\n    }\n\n    const handleCommit = async () => {\n        try {\n            await actions.commit()\n        } catch {\n            // ProjectSessionService emits the user-visible error.\n        }\n    }\n\n    const handlePush = async () => {\n        try {\n            await actions.push()\n        } catch {\n            // ProjectSessionService emits the user-visible error.\n        }\n    }\n\n    const handlePull = async () => {\n        try {\n            await actions.pull()\n        } catch {\n            // ProjectSessionService emits the user-visible error.\n        }\n    }\n\n    const handleViewModeChange = (_event: ReactMouseEvent<HTMLElement>, nextMode: WorkspaceViewMode | null) => {\n        if (!nextMode) return\n\n        workspaceViewService.setViewMode(nextMode)\n    }\n\n    const handleAgentChange = (event: SelectChangeEvent) => {\n        const profile = findAgentProfile(agentProfiles, event.target.value)\n        const nextModel = profile ? defaultModelForProfile(profile) : ''\n        configService.set('desktop.agent', event.target.value)\n        configService.set('desktop.model', nextModel)\n        persistDesktopConfig()\n    }\n\n    const setModel = (value: string) => {\n        configService.set('desktop.model', value)\n        persistDesktopConfig()\n    }\n\n    const handleModelSelectChange = (event: SelectChangeEvent) => {\n        setModel(event.target.value)\n    }\n\n    const handleModelTextChange = (event: ChangeEvent<HTMLInputElement>) => {\n        setModel(event.target.value)\n    }\n\n    const handleThinkingLevelChange = (event: SelectChangeEvent) => {\n        const thinkingLevel = validateThinkingLevel(event.target.value, 'Default reasoning level')\n        configService.set('desktop.thinkingLevel', thinkingLevel)\n        persistDesktopConfig()\n    }\n\n    const handleCreateAction = async () => {\n        if (!projectConfig) throw new Error('Cannot create an action before project config is loaded')\n\n        try {\n            const { definition, path } = actionService.createDefinition(projectConfig.actionsFolder)\n            await actionService.saveDefinition(path, definition)\n            workspaceViewService.setViewMode('text')\n            workspaceNavigationService.open(path)\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: 'Action creation failed' })\n        }\n    }\n\n    const handleDiscardGithubPendingCommits = () => {\n        if (!actions.pendingGithubConflictProject) return\n\n        projectSessionService.discardGithubPendingCommits(actions.pendingGithubConflictProject, accessToken)\n    }\n\n    const menuTabs = (\n        <Tabs\n            aria-label=\"Application menu\"\n            onChange={handleTabChange}\n            scrollButtons={false}\n            sx={{\n                minHeight: 44,\n                '& .MuiTabs-indicator': { height: 2 },\n            }}\n            value={currentTab}\n            variant=\"scrollable\"\n        >\n            {MENU_TABS.map((tab) => (\n                <MuiTab\n                    key={tab.value}\n                    label={tab.label}\n                    sx={{ fontSize: 13.5, minHeight: 44, minWidth: 0, px: 1.5, textTransform: 'none' }}\n                    value={tab.value}\n                />\n            ))}\n        </Tabs>\n    )\n\n    const viewSection = (\n        <Section label=\"View\">\n            <ToggleButtonGroup\n                exclusive\n                onChange={handleViewModeChange}\n                size=\"small\"\n                sx={{\n                    bgcolor: 'action.selected',\n                    borderRadius: 1,\n                    gap: 0.25,\n                    p: 0.375,\n                    '& .MuiToggleButtonGroup-grouped': { border: 0, borderRadius: '6px !important', height: 28, px: 1.25 },\n                    '& .Mui-selected': { bgcolor: 'background.paper', boxShadow: '0 1px 2px rgba(16,24,40,0.1)' },\n                }}\n                value={viewMode}\n            >\n                <Tooltip title=\"Cards view\">\n                    <ToggleButton aria-label=\"Cards view\" value=\"cards\">\n                        <CardsOutline fontSize=\"small\" />\n                        <Box component=\"span\" sx={{ ml: 0.75 }}>Board</Box>\n                    </ToggleButton>\n                </Tooltip>\n                <Tooltip title=\"Text view\">\n                    <ToggleButton aria-label=\"Text view\" value=\"text\">\n                        <TextBoxOutline fontSize=\"small\" />\n                        <Box component=\"span\" sx={{ ml: 0.75 }}>List</Box>\n                    </ToggleButton>\n                </Tooltip>\n            </ToggleButtonGroup>\n        </Section>\n    )\n\n    const menuPanel = (\n        <Menu>\n            <Box role=\"tabpanel\" sx={{ display: currentTab === 'home' ? 'block' : 'none' }}>\n                <Tab>\n                    {isMobile ? (\n                        <>\n                            {viewSection}\n                            <Divider flexItem orientation=\"vertical\" sx={{ my: 1.5 }} />\n                        </>\n                    ) : null}\n                    <Section label=\"Project\">\n                        <MenuIconButton label=\"Open project\" onClick={handleOpenProject}>\n                            <FolderOpen fontSize=\"small\" />\n                        </MenuIconButton>\n                        <BranchMenuSelect\n                            branches={branchOptions}\n                            disabled={!actions.isProjectOpen || actions.isLoading}\n                            onChange={handleBranchChange}\n                            onOpen={handleLoadBranches}\n                            value={selectedBranch}\n                        />\n                        <MenuIconButton\n                            disabled={!actions.isProjectOpen || actions.isLoading || !hasPendingSave}\n                            label=\"Commit\"\n                            onClick={handleCommit}\n                        >\n                            <ContentSaveOutline fontSize=\"small\" />\n                        </MenuIconButton>\n                        <MenuIconButton\n                            disabled={\n                                !actions.isProjectOpen\n                                || actions.isLoading\n                                || (!hasPendingPush && (primaryWorktreeStatus?.ahead ?? 0) <= 0)\n                            }\n                            label=\"Push\"\n                            onClick={handlePush}\n                        >\n                            <CloudArrowUpOutline fontSize=\"small\" />\n                        </MenuIconButton>\n                        <MenuIconButton\n                            disabled={\n                                !actions.isProjectOpen\n                                || actions.isLoading\n                                || hasPendingSave\n                                || hasPendingPush\n                                || !primaryWorktreeStatus?.hasUpstream\n                                || primaryWorktreeStatus.dirty\n                                || primaryWorktreeStatus.ahead > 0\n                                || primaryWorktreeStatus.behind <= 0\n                            }\n                            label=\"Pull\"\n                            onClick={handlePull}\n                        >\n                            <CloudArrowDownOutline fontSize=\"small\" />\n                        </MenuIconButton>\n                    </Section>\n                    <Divider flexItem orientation=\"vertical\" sx={{ my: 1.5 }} />\n                    <Section label=\"Settings\">\n                        <MenuIconButton label=\"Config\" onClick={onOpenConfig}>\n                            <Cog fontSize=\"small\" />\n                        </MenuIconButton>\n                        {extraActions}\n                    </Section>\n                    {!isMobile ? (\n                        <>\n                            <Divider flexItem orientation=\"vertical\" sx={{ my: 1.5 }} />\n                            {viewSection}\n                            <Divider flexItem orientation=\"vertical\" sx={{ my: 1.5 }} />\n                            <Button disabled={!project} onClick={handleCreateAction} size=\"small\" variant=\"outlined\">New action</Button>\n                            <Button\n                                disabled={!actions.isProjectOpen}\n                                onClick={handleOpenCardDialog}\n                                size=\"small\"\n                                startIcon={<FileDocumentPlusOutline fontSize=\"small\" />}\n                                sx={{ height: 34, px: 1.75 }}\n                                variant=\"contained\"\n                            >\n                                New card\n                            </Button>\n                            <Box sx={{ flex: 1 }} />\n                            <Section label=\"Account\">\n                                <GithubAuthToolbarButton auth={auth} />\n                            </Section>\n                        </>\n                    ) : null}\n                </Tab>\n            </Box>\n            <Box role=\"tabpanel\" sx={{ display: currentTab === 'agents' ? 'block' : 'none' }}>\n                <Tab>\n                    <Section label=\"Setup\">\n                        <MenuSelect\n                            disabled={!desktopAvailable}\n                            label=\"Default agent\"\n                            minWidth={130}\n                            onChange={handleAgentChange}\n                            value={selectedAgent}\n                        >\n                            {agentProfiles.map((profile) => (\n                                <MenuItem key={profile.name} value={profile.name}>{profile.name}</MenuItem>\n                            ))}\n                        </MenuSelect>\n                        {selectedModels.length > 0 ? (\n                            <MenuSelect\n                                disabled={!desktopAvailable}\n                                label=\"Default model\"\n                                minWidth={150}\n                                onChange={handleModelSelectChange}\n                                value={selectedModel}\n                            >\n                                {selectedModels.map((model) => (\n                                    <MenuItem key={model} value={model}>{model}</MenuItem>\n                                ))}\n                            </MenuSelect>\n                        ) : (\n                            <Tooltip title=\"Default model\">\n                                <TextField\n                                    disabled={!desktopAvailable}\n                                    onChange={handleModelTextChange}\n                                    size=\"small\"\n                                    slotProps={{ htmlInput: { 'aria-label': 'Default model' } }}\n                                    style={NO_DRAG_REGION}\n                                    sx={{ width: 150 }}\n                                    value={selectedModel}\n                                />\n                            </Tooltip>\n                        )}\n                        <MenuSelect\n                            disabled={!desktopAvailable}\n                            label=\"Default reasoning level\"\n                            minWidth={120}\n                            onChange={handleThinkingLevelChange}\n                            value={selectedThinkingLevel}\n                        >\n                            {THINKING_LEVELS.map((level) => (\n                                <MenuItem key={level} value={level}>{level}</MenuItem>\n                            ))}\n                        </MenuSelect>\n                    </Section>\n                    <Divider flexItem orientation=\"vertical\" sx={{ my: 1.5 }} />\n                    <Section label=\"Actions\">\n                        <ActionEntryPoints context={PROJECT_CONTEXT} variant=\"icons\" visibility=\"explicit-context\" />\n                        <MenuIconButton\n                            disabled={!actions.isProjectOpen || actions.activeCards.length === 0 || actions.isReleaseCompleting}\n                            label=\"Complete release\"\n                            onClick={handleOpenReleaseDialog}\n                        >\n                            <CheckCircleOutline fontSize=\"small\" />\n                        </MenuIconButton>\n                    </Section>\n                </Tab>\n            </Box>\n            <ProjectOpenDialog\n                branches={actions.branches}\n                initialSource={actions.initialProjectSource}\n                isDesktopMode={actions.isDesktopMode}\n                isGithubAuthenticated={isGithubAuthenticated}\n                isLoading={actions.isLoading}\n                onCreateProjectFolders={handleCreateProjectFolders}\n                projectOpenResolution={actions.projectOpenResolution}\n                onBranchChange={() => undefined}\n                onClose={actions.closeDialog}\n                onCreateRemoteProject={actions.createRemoteProject}\n                onCreateWorkingFolder={() => void actions.createWorkingFolder()}\n                onDiscardGithubPendingCommits={handleDiscardGithubPendingCommits}\n                onLoadManualBranches={actions.loadManualBranches}\n                onLoadRemoteBranches={actions.loadRemoteBranches}\n                onOpenGithub={actions.openGithubProject}\n                onOpenRemote={actions.openRemoteProject}\n                onRepositoryChange={actions.loadRepositoryBranches}\n                onSourceChange={actions.clearOpenDialogState}\n                onUseWorkingFolder={(folder) => void actions.openWorkingFolder(folder)}\n                open={dialogMode === 'open'}\n                pendingGithubConflictProject={actions.pendingGithubConflictProject}\n                repositories={actions.repositories}\n            />\n            <BranchSwitchDialog\n                branches={actions.branches}\n                isLoading={actions.isLoading}\n                onBranchChange={actions.setSwitchBranch}\n                onClose={actions.closeDialog}\n                onSwitchBranch={(branch) => void actions.switchProjectBranch(branch)}\n                open={dialogMode === 'branch'}\n                selectedBranch={actions.switchBranch}\n            />\n            <CompleteReleaseDialog\n                isLoading={actions.isLoading}\n                onClose={actions.closeDialog}\n                onCompleteRelease={actions.completeRelease}\n                open={dialogMode === 'release'}\n            />\n            <NewCardDialog\n                cardBodyTemplate={actions.cardBodyTemplate}\n                cardTypes={actions.cardTypes}\n                isLoading={actions.isLoading}\n                isProjectOpen={actions.isProjectOpen}\n                onClose={actions.closeDialog}\n                onCreateCard={actions.createCard}\n                open={dialogMode === 'card'}\n            />\n        </Menu>\n    )\n\n    return (\n        <MainToolbar\n            isMobile={isMobile}\n            mobileAction={isMobile && currentTab === 'home' ? (\n                <MobileCreateMenu\n                    isNewActionDisabled={!project}\n                    isNewCardDisabled={!actions.isProjectOpen}\n                    onCreateAction={handleCreateAction}\n                    onCreateCard={handleOpenCardDialog}\n                />\n            ) : null}\n            onOpenMenu={onOpenMobileMenu}\n            panel={menuPanel}\n            search={search}\n            tabs={menuTabs}\n        />\n    )\n}\n\r\nimport { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react'\nimport { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'\nimport type { UseGithubAuthResult } from '../../../auth/use_github_auth'\nimport type { StorageService } from '../../../data/data_types'\nimport type { ElectronDataBridge } from '../../../data/electron_data_bridge'\nimport { actionService } from '../../../services/actions/action_service'\nimport { configService } from '../../../services/config/config_service'\nimport { dataService } from '../../../services/data/data_service'\nimport { workspaceNavigationService } from '../../../services/project/workspace_navigation_service'\nimport { workspaceViewService } from '../../../services/project/workspace_view_service'\nimport { projectPersistenceService } from '../../../services/project/project_persistence_service'\nimport { openFilesService } from '../../../services/open_files_service'\nimport { AppThemeProvider } from '../../../theme/theme_provider'\nimport { DialogDisplay } from '../../dialog_display'\nimport { AppMenu } from './app_menu'\n\nconst auth: UseGithubAuthResult = {\n    accessToken: null,\n    errorMessage: null,\n    isAuthenticated: false,\n    isLoadingUser: false,\n    logout: vi.fn(),\n    savePersonalAccessToken: vi.fn(),\n    status: 'idle',\n    user: null,\n}\n\nfunction createBridge(): ElectronDataBridge {\n    return {\n        checkoutBranch: vi.fn(async (project, branch) => ({ ...project, branch })),\n        commit: vi.fn(async () => []),\n        createProject: vi.fn(async (project) => project),\n        deleteFile: vi.fn(),\n        deleteFolder: vi.fn(),\n        hasPendingPush: vi.fn(async () => false),\n        listBranches: vi.fn(async () => [{ name: 'main' }]),\n        listRepositoryFiles: vi.fn(async () => []),\n        listTopLevelFolders: vi.fn(async () => [{ name: 'design', path: 'design' }]),\n        loadActionFiles: vi.fn(async () => []),\n        loadFile: vi.fn(async () => ({ content: '', path: 'design/empty.md' })),\n        loadProject: vi.fn(async () => ({ files: [], workingFolder: 'design' })),\n        loadProjectRoot: vi.fn(async () => ({ files: [], workingFolder: 'design' })),\n        loadProjectConfig: vi.fn(async () => ({ backgroundShade: 'blue' as const, projectFolder: '', workingFolder: 'design' })),\n        onWorktreesChanged: vi.fn(() => vi.fn()),\n        moveFiles: vi.fn(),\n        openProjectFolder: vi.fn(async () => ({ branch: 'main', id: 'local', rootPath: 'C:/repo' })),\n        pull: vi.fn(),\n        push: vi.fn(),\n        resolveProject: vi.fn(async (project) => project),\n        saveProjectConfig: vi.fn(),\n        addWorktree: vi.fn(async () => false),\n        removeWorktree: vi.fn(async () => undefined),\n        watchProject: vi.fn(() => vi.fn()),\n    }\n}\n\nfunction createResetStorage(): StorageService {\n    return {\n        checkoutBranch: vi.fn(async (project, branch) => ({ ...project, branch })),\n        commit: vi.fn(async () => []),\n        createProject: vi.fn(async (project) => project),\n        deleteFile: vi.fn(),\n        deleteFolder: vi.fn(),\n        listBranches: vi.fn(async () => []),\n        listRepositories: vi.fn(async () => []),\n        listRepositoryFiles: vi.fn(async () => []),\n        listTopLevelFolders: vi.fn(async () => []),\n        loadActionFiles: vi.fn(async () => []),\n        loadProject: vi.fn(async () => ({ files: [], workingFolder: 'design' })),\n        loadProjectRoot: vi.fn(async () => ({ files: [], workingFolder: 'design' })),\n        loadProjectConfig: vi.fn(async () => null),\n        moveFiles: vi.fn(),\n        push: vi.fn(),\n        saveProjectConfig: vi.fn(),\n    }\n}\n\nfunction renderMenu(isMobile = false) {\n    return render(\n        <AppThemeProvider>\n            <DialogDisplay />\n            <AppMenu\n                accessToken=\"token\"\n                auth={auth}\n                extraActions={null}\n                isGithubAuthenticated={false}\n                isMobile={isMobile}\n                onOpenConfig={vi.fn()}\n                onOpenMobileMenu={vi.fn()}\n                search={<input aria-label=\"Search project\" />}\n            />\n        </AppThemeProvider>,\n    )\n}\n\nasync function openLocalProject() {\n    fireEvent.click(screen.getByRole('button', { name: 'Open project' }))\n    await waitFor(() => expect(screen.queryByRole('dialog', { name: 'Open project' })).toBeNull())\n}\n\ndescribe('AppMenu', () => {\n    beforeEach(() => {\n        configService.init({ desktopConfig: null })\n        actionService.clear()\n        openFilesService.init({ actionService, dataService })\n        projectPersistenceService.init({ actionService, dataService, openFilesService })\n        dataService.init({ storage: createResetStorage() })\n        workspaceViewService.setViewMode('cards')\n        const { selectedPath } = workspaceViewService.getSnapshot()\n        if (selectedPath) workspaceViewService.clearSelectedPath(selectedPath)\n    })\n\n    afterEach(() => {\n        cleanup()\n        configService.clear()\n        actionService.clear()\n        window.localStorage.clear()\n        delete window.md2Data\n        vi.restoreAllMocks()\n    })\n\n    it('renders the requested top-level menu tabs and home sections', () => {\n        renderMenu()\n\n        expect(screen.getByRole('tab', { name: 'Home' })).toBeInTheDocument()\n        expect(screen.queryByRole('tab', { name: 'Edit' })).not.toBeInTheDocument()\n        expect(screen.queryByRole('tab', { name: 'Format' })).not.toBeInTheDocument()\n        expect(screen.getByRole('tab', { name: 'Run' })).toBeInTheDocument()\n        expect(screen.getByRole('button', { name: 'Open project' })).toBeInTheDocument()\n        expect(screen.getByRole('button', { name: 'Commit' })).toBeDisabled()\n        expect(screen.getByRole('button', { name: 'Push' })).toBeDisabled()\n        expect(screen.getByRole('button', { name: 'Pull' })).toBeDisabled()\n        expect(screen.getByRole('button', { name: 'Config' })).toBeInTheDocument()\n        expect(screen.getByRole('button', { name: 'Cards view' })).toHaveTextContent('Board')\n        expect(screen.getByRole('button', { name: 'Text view' })).toHaveTextContent('List')\n        expect(screen.getByRole('button', { name: 'New action' })).toBeInTheDocument()\n        expect(screen.getByRole('button', { name: 'New card' })).toBeInTheDocument()\n        expect(screen.getByRole('button', { name: 'GitHub account' })).toBeInTheDocument()\n\n        const settingsSection = screen.getByRole('group', { name: 'Settings' })\n        const viewSection = screen.getByRole('group', { name: 'View' })\n        expect(settingsSection.compareDocumentPosition(viewSection) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy()\n\n        expect(screen.queryByRole('button', { name: 'Complete release' })).not.toBeInTheDocument()\n\n        fireEvent.click(screen.getByRole('tab', { name: 'Run' }))\n\n        const completeReleaseButton = screen.getByRole('button', { name: 'Complete release' })\n        const newCardButton = screen.getByRole('button', { name: 'New card', hidden: true })\n        expect(completeReleaseButton).toBeInTheDocument()\n        expect(newCardButton).not.toBeVisible()\n        expect(screen.getByRole('button', { name: 'New action', hidden: true })).not.toBeVisible()\n    })\n\n    it('renders mobile Home controls in responsive order and hides desktop-only actions', () => {\n        renderMenu(true)\n\n        const viewSection = screen.getByRole('group', { name: 'View' })\n        const projectSection = screen.getByRole('group', { name: 'Project' })\n        const openProjectButton = screen.getByRole('button', { name: 'Open project' })\n        const branchSelect = screen.getByRole('combobox', { name: 'Switch branch' })\n        expect(viewSection.compareDocumentPosition(projectSection) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy()\n        expect(openProjectButton.compareDocumentPosition(branchSelect) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy()\n        expect(screen.queryByRole('button', { name: 'New action' })).toBeNull()\n        expect(screen.queryByRole('button', { name: 'New card' })).toBeNull()\n        expect(screen.queryByRole('button', { name: 'GitHub account' })).toBeNull()\n        expect(screen.getByRole('button', { name: 'Create' })).toBeInTheDocument()\n    })\n\n    it('keeps the mobile create menu on Home and preserves the Run toolbar', () => {\n        renderMenu(true)\n\n        fireEvent.click(screen.getByRole('button', { name: 'Create' }))\n        expect(screen.getByRole('menuitem', { name: 'New action' })).toHaveAttribute('aria-disabled', 'true')\n        expect(screen.getByRole('menuitem', { name: 'New card' })).toHaveAttribute('aria-disabled', 'true')\n        fireEvent.keyDown(screen.getByRole('menu'), { key: 'Escape' })\n\n        fireEvent.click(screen.getByRole('tab', { name: 'Run' }))\n\n        expect(screen.queryByRole('button', { name: 'Create' })).toBeNull()\n        expect(screen.getByRole('button', { name: 'Complete release' })).toBeInTheDocument()\n    })\n\n    it('runs both mobile create actions through their existing handlers', async () => {\n        const bridge = createBridge()\n        window.md2Data = bridge\n        const listener = vi.fn()\n        workspaceNavigationService.addEventListener('open', listener)\n        renderMenu(true)\n        await openLocalProject()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Create' }))\n        fireEvent.click(screen.getByRole('menuitem', { name: 'New card' }))\n        expect(screen.getByRole('dialog', { name: 'New card' })).toBeInTheDocument()\n        fireEvent.click(screen.getByRole('button', { name: 'Cancel' }))\n        await waitFor(() => expect(screen.queryByRole('dialog', { name: 'New card' })).toBeNull())\n\n        fireEvent.click(screen.getByRole('button', { name: 'Create' }))\n        fireEvent.click(screen.getByRole('menuitem', { name: 'New action' }))\n        await waitFor(() => expect(listener).toHaveBeenCalledOnce())\n\n        workspaceNavigationService.removeEventListener('open', listener)\n    })\n\n    it('opens a local project from the Home project section', async () => {\n        const bridge = createBridge()\n        window.md2Data = bridge\n\n        renderMenu()\n        await openLocalProject()\n\n        expect(dataService.getState().project?.id).toBe('local')\n    })\n\n    it('updates the shared workspace view mode from the Home view toggle', () => {\n        renderMenu()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Text view' }))\n\n        expect(workspaceViewService.getSnapshot().viewMode).toBe('text')\n    })\n\n    it('creates a valid action and opens its text-view tab from the Home tab', async () => {\n        const bridge = createBridge()\n        window.md2Data = bridge\n        const listener = vi.fn()\n        workspaceNavigationService.addEventListener('open', listener)\n        renderMenu()\n        await openLocalProject()\n\n        fireEvent.click(screen.getByRole('button', { name: 'New action' }))\n\n        await waitFor(() => expect(listener).toHaveBeenCalledOnce())\n        await projectPersistenceService.flushPendingChanges()\n        const commitRequest = vi.mocked(bridge.commit).mock.calls.at(-1)?.[0]\n        const actionFile = commitRequest?.files[0]\n        if (!actionFile) throw new Error('Missing persisted action file')\n        const persistedDefinition = JSON.parse(actionFile.content) as { id: string, label: string }\n\n        expect(actionFile.content).toMatch(/\\{\\n {2}\"description\": \"Describe this action\\.\",/u)\n        expect(actionService.getActionByPath(actionFile.path)).toMatchObject({\n            id: persistedDefinition.id,\n            label: persistedDefinition.label,\n            sourcePath: actionFile.path,\n        })\n        expect(workspaceViewService.getSnapshot().viewMode).toBe('text')\n        expect(listener).toHaveBeenCalledOnce()\n        expect((listener.mock.calls[0][0] as CustomEvent<{ path: string }>).detail.path).toBe(actionFile.path)\n\n        actionService.loadFromFiles([actionFile])\n        expect(actionService.getActionByPath(actionFile.path)).toMatchObject({\n            id: persistedDefinition.id,\n            label: persistedDefinition.label,\n            sourcePath: actionFile.path,\n        })\n        workspaceNavigationService.removeEventListener('open', listener)\n    })\n\n    it('shows a Run button for every explicitly project-scoped action', async () => {\n        const bridge = createBridge()\n        bridge.loadActionFiles = vi.fn(async () => [\n            {\n                content: JSON.stringify({\n                    appliesTo: { kind: 'project' }, command: 'review', description: 'Review project',\n                    id: 'project-review', label: 'Review project', type: 'command',\n                }),\n                path: 'design/actions/project-review.json',\n            },\n            {\n                content: JSON.stringify({\n                    appliesTo: { kind: 'card' }, command: 'review', description: 'Review card',\n                    id: 'card-review', label: 'Review card', type: 'command',\n                }),\n                path: 'design/actions/card-review.json',\n            },\n        ])\n        window.md2Data = bridge\n\n        renderMenu()\n        await openLocalProject()\n        fireEvent.click(screen.getByRole('tab', { name: 'Run' }))\n\n        expect(screen.getByRole('button', { name: 'Review project' })).toBeInTheDocument()\n        expect(screen.queryByRole('button', { name: 'Review card' })).not.toBeInTheDocument()\n        expect(screen.queryByRole('button', { name: 'Custom prompt' })).not.toBeInTheDocument()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Review project' }))\n        const dialog = within(screen.getByRole('dialog', { name: 'Run actions' }))\n        expect(dialog.getByRole('button', { name: 'Review project' })).toHaveAttribute('aria-pressed', 'true')\n    })\n\n    it('shows and refreshes the default agent settings', async () => {\n        configService.clear()\n        configService.init({\n            desktopConfig: {\n                agent: 'codex',\n                agentProfiles: [\n                    { command: ['codex'], modelArgument: '--model', models: ['gpt-5'], name: 'codex' },\n                    { command: ['local-agent'], modelArgument: '--model', models: ['local-model'], name: 'local' },\n                ],\n                model: 'gpt-5',\n                thinkingLevel: 'high',\n            },\n        })\n\n        renderMenu()\n        fireEvent.click(screen.getByRole('tab', { name: 'Run' }))\n\n        expect(screen.getByRole('combobox', { name: 'Default agent' })).toHaveTextContent('codex')\n        expect(screen.getByRole('combobox', { name: 'Default model' })).toHaveTextContent('gpt-5')\n        expect(screen.getByRole('combobox', { name: 'Default reasoning level' })).toHaveTextContent('high')\n\n        fireEvent.mouseOver(screen.getByRole('combobox', { name: 'Default reasoning level' }))\n        expect(await screen.findByRole('tooltip')).toHaveTextContent('Default reasoning level')\n\n        fireEvent.mouseDown(screen.getByRole('combobox', { name: 'Default reasoning level' }))\n        fireEvent.click(screen.getByRole('option', { name: 'max' }))\n        expect(configService.get('desktop.thinkingLevel')).toBe('max')\n\n        act(() => {\n            configService.set('desktop.agent', 'local')\n            configService.set('desktop.model', 'local-model')\n            configService.set('desktop.thinkingLevel', 'low')\n        })\n\n        await waitFor(() => expect(screen.getByRole('combobox', { name: 'Default agent' })).toHaveTextContent('local'))\n        expect(screen.getByRole('combobox', { name: 'Default model' })).toHaveTextContent('local-model')\n        expect(screen.getByRole('combobox', { name: 'Default reasoning level' })).toHaveTextContent('low')\n    })\n\n    it('commits pending changes before enabling manual push', async () => {\n        const bridge = createBridge()\n        const files = [{ content: '---\\nid: F-1\\ninternalId: f-1\\ntitle: Root\\nstatus: active\\n---\\n\\n# Root', path: 'design/F-1-root.md' }]\n        bridge.loadProjectConfig = vi.fn(async () => ({\n            backgroundShade: 'blue' as const,\n            projectFolder: '',\n            pushMode: 'manual' as const,\n            workingFolder: 'design',\n        }))\n        bridge.loadProject = vi.fn(async () => ({ files, workingFolder: 'design' }))\n        bridge.loadProjectRoot = vi.fn(async () => ({ files, workingFolder: 'design' }))\n        window.md2Data = bridge\n\n        renderMenu()\n        await openLocalProject()\n        const commitButton = screen.getByRole('button', { name: 'Commit' })\n        const pushButton = screen.getByRole('button', { name: 'Push' })\n        expect(commitButton).toBeDisabled()\n        expect(pushButton).toBeDisabled()\n\n        act(() => {\n            dataService.cards.updateCardBody('design/F-1-root.md', 'Changed before push')\n        })\n\n        await waitFor(() => expect(commitButton).toBeEnabled())\n        expect(pushButton).toBeDisabled()\n        fireEvent.click(commitButton)\n\n        await waitFor(() => expect(bridge.commit).toHaveBeenCalled())\n        await waitFor(() => expect(pushButton).toBeEnabled())\n        fireEvent.click(pushButton)\n\n        await waitFor(() => expect(bridge.push).toHaveBeenCalledWith(expect.objectContaining({ id: 'local' })))\n        expect(pushButton).toBeDisabled()\n    })\n\n    it('pulls only when the primary worktree monitor reports clean incoming commits', async () => {\n        let onWorktreesChanged: ((state: {\n            error: string | null\n            primaryStatus: {\n                ahead: number\n                baseAhead: number\n                baseBehind: number\n                behind: number\n                dirty: boolean\n                hasUpstream: boolean\n            }\n            project: { branch: string, id: string, rootPath: string }\n            records: []\n        }) => void) | null = null\n        const bridge = createBridge()\n        bridge.onWorktreesChanged = vi.fn((callback) => {\n            onWorktreesChanged = callback\n\n            return vi.fn()\n        })\n        window.md2Data = bridge\n        renderMenu()\n        await openLocalProject()\n        const pullButton = screen.getByRole('button', { name: 'Pull' })\n        expect(pullButton).toBeDisabled()\n\n        act(() => {\n            onWorktreesChanged?.({\n                error: null,\n                primaryStatus: { ahead: 0, baseAhead: 0, baseBehind: 0, behind: 1, dirty: false, hasUpstream: true },\n                project: { branch: 'main', id: 'local', rootPath: 'C:/repo' },\n                records: [],\n            })\n        })\n\n        await waitFor(() => expect(pullButton).toBeEnabled())\n        fireEvent.click(pullButton)\n        await waitFor(() => expect(bridge.pull).toHaveBeenCalledWith(expect.objectContaining({ id: 'local' })))\n    })\n})\n\r\n",
.\design\activity\card__fb3a7428-2f7d-48dd-beda-ce7279c516e7.json:317:          "content": "design\\feature_descriptions\\F-46-git-worktrees.md\r\n---\nid: F-10\ntitle: Git worktrees\nstatus: ready\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: 85f226c7-ca58-4a90-a80b-f783769f0fb9\n---\n\n## Goal\n\nAllow Electron to manage linked Git worktrees, assign cards to them, run `needsWorkTree` actions in the assigned worktree, and show worktree/agent state on each card.\n\n## Git model and terminology\n\n- **Primary worktree**: the repository folder currently opened by Electron. It is not necessarily a branch named `main`.\n- **Linked worktree**: another folder created through `git worktree add`.\n- **Card worktree**: the linked worktree assigned to a card.\n- **Parking branch**: an MDÂ²-owned `md2/parking/*` branch that keeps an unassigned linked worktree at the opened project branch commit.\n- Git worktrees share one object database but normally check out different branches.\n- One linked worktree can be reserved by only one active card. Background cards do not reserve worktrees.\n- Project-agent session assignments can use any linked worktree, including one reserved by a card.\n- Config can create and remove linked worktrees. Removing one deletes its checkout folder but retains its branch and commits.\n- Action execution only uses linked worktrees reported by Git; it never creates one.\n\n## Current state\n\n- Worktree management, card assignment, and validation exist.\n- The implemented action model uses `runIn: \"project\" | \"card\"` and can automatically transfer successful project-worktree changes to a card worktree.\n- The action model must migrate to `needsWorkTree`; automatic commit/cherry-pick transfer must be removed without a legacy fallback.\n\n## Implementation details\n\n### Worktree discovery and identity\n\n- Load linked worktrees directly from `git worktree list --porcelain`; do not persist a separate MDÂ² worktree registry.\n- Exclude the currently opened primary worktree from the linked-worktree list.\n- Git list position is identity: the first linked folder is worktree `1`, the second is `2`, and so on.\n- Store a card's one-based worktree index in frontmatter as `worktree: <number>`. A missing field means no assigned linked worktree.\n- Invalid indices remain visible as card errors; never silently fall back.\n- Detached, locked, and prunable worktrees remain visible with their exact invalid state.\n\n### Config UI\n\n- Show the worktree list in Config > Project as an Electron-only control.\n- Display linked folder paths in Git order.\n- `+` opens an Electron folder picker, runs `git worktree add <folder>`, and switches the checkout to its MDÂ² parking branch.\n- Removing an entry requires confirmation and runs non-forced `git worktree remove`; Git rejects dirty or locked worktrees.\n- Add and remove apply immediately and do not participate in Config Save or Cancel.\n\n### Card assignment and indicator\n\n- Use `CardWorktreeIndicator` in the lower-right of board cards.\n- Show the stored one-based worktree index and allow assignment to Primary/unassigned or any valid linked worktree.\n- Disable worktrees reserved by another active card. The card's current assignment remains available to itself.\n- Derive the card branch by slugifying the card id and title with the configured card separator.\n- Reuse the current card branch even when dirty. A dirty worktree on another branch blocks assignment.\n- For a clean worktree, switch to an existing card branch or create it from the opened project branch, then persist the assignment.\n- An assigned card selector shows Primary, Commit, Update worktree, and Integrate into project instead of other linked-worktree choices.\n- Commit stages all worktree changes. Update flushes pending project saves, checkpoints remaining primary-worktree changes, and rebases the worktree onto the opened project branch. Integrate performs the same project checkpoint, rebases when needed, and fast-forwards the opened project branch to the worktree branch.\n- Returning to Primary parks a synchronized worktree before clearing the assignment. Dirty worktrees require Commit & integrate or explicit destructive discard.\n- Card indicators and menu availability use the same project-to-worktree comparison. Up means dirty or ahead of the project branch; down means pending project saves or behind the project branch. Upstream state is handled by project-level synchronization.\n- Background cards do not reserve their stored worktree. Project-agent assignment does not use card reservations and does not prepare a branch.\n- Invalid/out-of-range assignments remain visible in red with the exact validation error.\n- Preserve the aggregate card-agent states: running, waiting for input, completed/failed unseen, and idle/acknowledged.\n- Do not infer waiting state from stdout text; an Electron adapter must emit it explicitly.\n- Preserve conversation UI in text view, action history, and the global running-actions indicator.\n\n### Action definition and execution\n\n- Replace `runIn` with optional boolean `needsWorkTree`. Omitted or `false` runs in the currently opened project folder.\n- When `needsWorkTree` is true and a card already has a valid assigned worktree, run in that worktree.\n- When `needsWorkTree` is true, reject an unassigned card or a non-card context before starting a process.\n- Resolve the card's one-based worktree value against Git's current linked-worktree list and reject missing, invalid, or unavailable entries with the exact validation error.\n- Resolve `{{rootProjectFolder}}`, file paths, agent logs, action history, and diff metadata against the prepared execution worktree.\n- The renderer sends only action id, context, and run-specific input. Electron reloads the definition, resolves `needsWorkTree`, and validates the selected worktree.\n- Apply `needsWorkTree` to each linked action when it executes through the Electron `onBefore`/main/`on`/`onAfter` chain.\n- Selector-time card worktree preparation only selects or creates the card branch.\n- Action execution resolves the prepared assignment but never creates, removes, assigns, or prepares a worktree.\n\n## Edge cases and failure modes\n\n- A detached, locked, or prunable worktree reports its exact invalid state.\n- Adding or removing a worktree can shift list indices; cards retain their stored values.\n- A dirty worktree on another branch blocks preparation and shows the Git error.\n- A card branch checked out by another linked worktree remains a Git error.\n- Update and integration reject unresolved dirty linked-worktree state. Remaining primary-worktree changes receive a local checkpoint commit before synchronization.\n- Failed commit, update, integration, discard, or parking leaves the card assigned.\n- Concurrent assignment attempts cannot reserve the same worktree for two active cards.\n- An unassigned card or non-card context cannot run an action that requires a worktree.\n- Card rename or move retains its worktree assignment.\n- Worktree update and integration report their own process result. Action completion adds no implicit cross-worktree transfer.\n\n## Testing implications\n\n- Add Git integration tests using temporary repositories and real `git worktree add`: discovery, creation, removal, branch retention, assignment, and detached worktrees.\n- Add Config tests for display, immediate add, confirmed remove, and error reporting.\n- Add card/data tests for worktree frontmatter, assignment, invalid states and agent-state decoration.\n- Add shared action-definition tests for `needsWorkTree` and rejection of legacy `runIn`.\n- Add Electron action-runner tests for primary/card execution, missing assignments, non-card contexts, invalid configured entries, linked actions, and schedules.\n- Add regression tests proving action completion performs no automatic commit, push, merge, cherry-pick, or cross-worktree transfer.\n- Run `npm run lint-fix`, `npm run lint`, and `npm run test` in both `app/` and `desktop/` during implementation.\n\n## Acceptance criteria\n\n- Electron users can add, view, and remove linked worktrees from Config > Project.\n- Active cards cannot select a worktree reserved by another active card; background cards release their reservation.\n- Successful card assignment reuses its id/title branch or creates it from the opened project branch before persisting the worktree index.\n- Dirty worktrees on another branch fail without changing the card assignment; dirty worktrees already on the card branch are reused.\n- Returning to Primary resolves dirty changes and restores the linked worktree parking branch before clearing the assignment.\n- Assigned-card menus expose commit, update-from-project, and integrate-into-project operations.\n- Card indicators expose dirty/ahead/behind state.\n- Git is the sole worktree source; card assignments use one-based indices from Git's current linked-worktree order.\n- Invalid assignments remain visible, explain the problem, and cannot be used for execution.\n- Actions without `needsWorkTree` run in the opened project folder.\n- Actions with `needsWorkTree` use the card's valid assigned worktree and reject missing assignments or non-card contexts.\n- Action execution does not create, remove, or assign worktrees.\n- Git preparation errors are visible before process start.\n- Action completion never performs automatic commit, update, integration, or cross-worktree transfer.\n\n## Open decisions\n\n- Define which agent adapter events mean `waiting for input` and `resumed`.\n- Define which interaction acknowledges `done but unseen` and where that local state is stored.\n\n## see also\n\n- `design\\feature_descriptions\\ready\\F_010_actions.md`\n- `design\\feature_descriptions\\ready\\F_023_agent_streaming.md`\n- `design\\architecture\\initial description\\writings\\running_actions.md`\n\r\ndesign\\feature_descriptions\\F-7-electron-local-folder-project-mode.md\r\n---\nid: F-7\ntitle: Electron local-folder project mode\nstatus: ready\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: b1fa4c6c-d86c-4917-a5ab-85742a793cef\n---\n\n## Goal\nMake the Electron application open a local project folder containing a Git repository and use that folder as the authoritative source for every project operation. GitHub repository opening remains a browser-app workflow; a GitHub remote in the selected local repository is handled through normal local Git commands.\n\n## Current state\nMost of the local implementation already exists. `LocalGitStorageService` routes file, config, branch, commit, push and watch operations through `window.md2Data`; Electron also runs actions, agents and diffs against `project.rootPath`.\n\nThe project-opening boundary is inconsistent:\n- Electron exposes a native folder picker through a dedicated `md2-data:open-project-folder` IPC channel. That path returns a raw string and overrides the generic `openProjectFolder` bridge method, although React expects a `ProjectReference`.\n- `local_bridge_dispatch.js` already has the correct flow for converting a selected path into a local project, validating it and establishing the current Electron project, but the renderer does not reach that flow.\n- The Electron project dialog still defaults to GitHub and treats Local as an optional source. The existing desktop config value `projectLocationMode: 'folder'` is not consumed by the React project-opening flow.\n- A locally selected branch is recorded in the React project reference without checking it out first. The displayed branch can therefore disagree with the files in the working tree.\n- Repository validation only checks for a `.git` directory, which rejects valid Git worktrees where `.git` is a file and does not normalize a nested selection to its repository root.\n\n## implementation details\n- Treat the presence of the trusted Electron data bridge as desktop local-folder mode. In this mode, the Open Project command opens the native folder picker directly; do not offer GitHub or remote project sources in the Electron open flow.\n- Keep browser behavior unchanged: without the Electron bridge, projects can still be opened through GitHub or remote control.\n- Route `openProjectFolder` through the existing local bridge dispatcher. Remove the duplicate picker result path that returns a raw string, so the renderer always receives a validated `ProjectReference`.\n- Resolve the selected folder with Git (`git rev-parse --show-toplevel`) and require a valid work tree. Normalize the returned `rootPath` and `id` to the repository root. A selection outside a Git work tree must fail with a clear dialog error.\n- Read the actual checked-out branch when creating the local project reference instead of defaulting to `main`. Define and report a clear state for a detached `HEAD`; do not label it as `main`.\n- Open the currently checked-out branch immediately after folder selection. Keep branch changes in the existing branch-switch command, which must call the local checkout operation before reloading project files.\n- Continue using `LocalGitStorageService` for project data. File reads and writes, project config, actions, schedules, agent logs, diffs, commits, branch changes, pushes and file watching must remain rooted under the normalized project folder.\n- Use the local repository's configured Git remotes and the user's Git credential manager or SSH setup for push. Electron project opening must not require GitHub authentication or instantiate `GithubStorageService`.\n- Preserve last-project restore for local projects. On startup, revalidate the stored root as a Git work tree before loading it and surface a clear error if the folder was moved, deleted or is no longer a repository.\n- Do not change remote-control semantics: a browser client may still use the separate remote-control storage flow to operate through an Electron host.\n- Keep path-escape validation for every filesystem operation. Folder selection grants access only to the normalized project root, not arbitrary filesystem paths.\n\n## Edge cases and failure modes\n- The user cancels the native folder picker: leave the current project unchanged and show no error.\n- The selected folder is inside a repository: normalize it to the top-level repository folder.\n- The selected folder is a Git worktree: accept it even when `.git` is a file.\n- Git is unavailable, the folder is not a work tree, or the repository cannot be read: reject the selection with a user-visible error.\n- The repository has a detached `HEAD`: report that state explicitly and do not invent a branch name.\n- Checkout is blocked by uncommitted changes: preserve the working tree, keep the current project open and show Git's failure through `dialogService`.\n- The stored last-project folder no longer exists: finish application startup without an open project and show the restore error.\n\n## testing implications\n- Add Electron bridge tests proving that folder selection returns a complete local project reference, validates through Git and establishes the current project used by data and action methods.\n- Add Git service tests for repository-root normalization, nested selections, worktrees, non-repositories and detached `HEAD`.\n- Add React tests proving that Electron mode opens a folder-only flow, does not require GitHub authentication and opens the detected current branch.\n- Add regression coverage proving the renderer no longer receives a raw folder-path string and that selecting a branch cannot relabel the project without checkout.\n- Keep browser GitHub and remote-control project-opening tests unchanged.\n\n## acceptance criteria\n- In Electron, Open Project shows a native folder picker and does not ask for a GitHub repository, GitHub login or remote endpoint.\n- Selecting a folder in a Git work tree opens the normalized repository root and displays its actual checked-out branch.\n- Selecting a non-repository folder shows a clear error and does not replace the current project.\n- All project data operations and all action, agent and diff operations use files under the selected repository root through the Electron bridge.\n- Branch switching performs a real local Git checkout before project content is reloaded.\n- Push uses the local repository's configured remote and local Git credentials.\n- The last local project restores on Electron startup after repository revalidation.\n- Browser GitHub opening and browser-to-Electron remote-control opening continue to work.\n\n## see also\n- `design\\feature_descriptions\\ready\\F_002_data_management.md`\n- `design\\feature_descriptions\\ready\\F_013_desktop_app.md`\n- `design\\feature_descriptions\\ready\\F_027_repository_branch_selection.md`\n- `design\\feature_descriptions\\ready\\B_029_desktop_bridge_security_hardening.md`\n- `design\\architecture\\initial description\\desktop app.md`\n\r\ndesign\\feature_descriptions\\F-8-signed-windows-electron-package-with-bundled-react-app.md\r\n---\nid: F-8\ntitle: Signed Windows Electron package with bundled React app\nstatus: design\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: 964fdcac-159c-49dc-af83-79f532e9651d\nafter: 0f92d6ef-ec13-478c-b3f9-d1b0bfcf391d\n---\n\n## Goal\nProduce an installable, Authenticode-signed Windows Electron application that contains the React production build and runs without a separately hosted website or development server.\n\n## Current state\nDevelopment starts Vite on `http://localhost:5173` and then launches Electron. `desktop/main.js` always calls `window.loadURL(appUrl)`, with the URL defaulting to the Vite development server. The React app has a production build command, but that output is not included in an Electron package.\n\nThere is no Electron packaging tool or configuration, Windows installer target, application icon, production renderer-loading path, signing configuration, packaging script or packaged-application smoke test. The desktop package can only be started from its source checkout.\n\n## implementation details\n- Use `electron-builder` in the desktop build toolchain and produce a Windows x64 NSIS installer. Also retain the unpacked application output for local smoke testing; portable distribution, auto-update and release publishing are outside this feature.\n  - use `npm install` an don't manually add `electron-builder` to `package.json`.\n- Add a root build command that runs the React production build first and then packages Electron. The package must include only the required Electron runtime files, production dependencies, shared runtime modules and built React assets.\n- Bundle application code in the default ASAR archive. Place the React build at a deterministic packaged path that `desktop/main.js` can resolve without depending on the source checkout.\n- Keep development behavior unchanged: an unpackaged Electron process loads the configured Vite URL. A packaged process loads the bundled React entry point and must not use `MD2_APP_URL` as its normal renderer source.\n- Configure Vite asset paths for packaged loading so JavaScript, CSS, fonts, icons and other assets resolve from the bundled entry point. Direct startup must not produce a blank window or failed `/assets/...` requests.\n- Update the preload origin/trust check for the packaged renderer. The bundled page receives the privileged bridges; navigations or popups to remote content must not receive them. Preserve `contextIsolation: true`, `nodeIntegration: false` and `sandbox: true`.\n- Prevent unexpected navigation away from the bundled application and open approved external links in the user's default browser rather than inside the privileged application window.\n- Define stable Windows metadata: application id, product name, executable name, publisher name, version and copyright. Derive the package version from one authoritative package version rather than maintaining unrelated versions manually.\n- Create a Windows `.ico` asset from the existing MDÂ² branding and use it for the executable, window and NSIS installer. Do not use Electron's default icon in release artifacts.\n- Sign the application executable and installer with the user's Windows application certificate through electron-builder's signing support. Use `WIN_CSC_LINK` and `WIN_CSC_KEY_PASSWORD` for an exportable PFX/P12 certificate; if the available certificate is hardware-backed or installed in the Windows certificate store, select it by its supported subject name or thumbprint instead.\n- Enable mandatory signing for release builds so missing, expired or invalid signing configuration fails the build instead of silently producing unsigned artifacts. Use a trusted timestamp service so the signature remains valid after certificate expiry.\n- Keep the certificate file, password, private key and encoded certificate out of source control, package contents and logs. Document the required environment variables or certificate-store setup for local and CI builds.\n- Write artifacts to an ignored output directory with predictable names containing the product version and architecture.\n- Do not add automatic update checks, GitHub release upload, Microsoft Store/MSIX packaging or non-Windows targets in this feature.\n\n## Edge cases and failure modes\n- The React build fails: do not run packaging with stale renderer assets.\n- Renderer assets are missing from the package: fail the build or smoke test before distribution.\n- Signing credentials are absent or invalid: fail the release package command and do not retain an apparently releasable unsigned installer.\n- The certificate is hardware-backed: support signing on the Windows machine that owns the key; do not attempt to export the private key into the repository or CI.\n- The installed application starts without a network connection: the bundled UI and local-folder project flow must remain usable.\n- Paths contain spaces or non-ASCII characters: the installed application, bundled renderer and selected project folder must still load correctly.\n- The application is installed over an older version: preserve Electron-store desktop settings and do not store writable user data inside the application installation or ASAR.\n\n## testing implications\n- Keep `npm run lint` and `npm run test` mandatory in both `app/` and `desktop/` before packaging; run the React typecheck/build as part of the package command.\n- Add tests for development-versus-packaged renderer resolution and for rejection of remote navigation in the privileged window.\n- Add a packaging verification step that checks the expected React entry point, preload, main-process files and required production dependencies are present in the packaged application.\n- Smoke-test the unpacked application and installed NSIS build on Windows without Vite or a network connection. Open a local Git project and exercise a read, edit/commit, branch list and action invocation.\n- Verify both the packaged executable and installer with `Get-AuthenticodeSignature`; require a valid signature, the expected publisher and a timestamp.\n- Confirm no certificate material, signing password, development source map or development-server URL is present in the artifacts.\n\n## acceptance criteria\n- One documented command builds the React app and creates a versioned Windows x64 NSIS installer plus an unpacked smoke-test application.\n- The installed application starts without Vite, a hosted website or network access and loads the bundled React UI.\n- The packaged UI receives the required Electron bridges and can open and operate on a local Git project.\n- Remote navigation cannot retain access to the privileged preload bridges.\n- The application executable and installer have valid Authenticode signatures from the configured application certificate and include a trusted timestamp.\n- A release build fails when signing is required but cannot be completed.\n- The installer, executable and Windows application list use MDÂ² product metadata and branding rather than Electron defaults.\n- Signing secrets and private certificate material are absent from Git history and packaged artifacts.\n- Existing desktop settings survive an application upgrade.\n\n## see also\n- `design\\feature_descriptions\\F_041_electron_local_folder_projects.md`\n- `design\\feature_descriptions\\ready\\F_013_desktop_app.md`\n- `design\\feature_descriptions\\ready\\B_015_electron_context_isolation.md`\n- `design\\feature_descriptions\\ready\\B_029_desktop_bridge_security_hardening.md`\n- `design\\architecture\\initial description\\desktop app.md`\n\n\r\ndesign\\feature_descriptions\\F_002_data_management.md\r\n---\nid: F-002\ntitle: data management\nstatus: ready\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: 2e7fb122-602f-46fa-b976-5fb68c8d7680\n---\n\n## Goal\nImplement the two-layer data service (generic data service + storage services for GitHub web API and local Git via Electron) covering project create/open, branch switching, card creation, naming conventions, auto-save with delayed commits, and auto/manual push.\n\n## Current state\nOnly the design notes exist. There is no React app, Electron bridge, data service, storage service, project loader, GitHub persistence, local Git persistence or file watcher implemented yet.\n\n## implementation details\n- Add a generic data service API for project, branch, file and card operations. Keep storage-specific behavior behind storage service implementations.\n- Implement a GitHub storage service using the GitHub web API for repository/branch selection, file reads/writes, commits and pushes.\n- Implement a local Git storage service exposed by Electron for opening a local `.git` folder, reading/writing files, running Git commands and watching file changes.\n- Project create/open loads the configured working folder, defaults to `design`, asks for another folder if missing, and can create template content when no folder exists.\n- Card creation writes a markdown file in the working folder using `{id}-{title}.md`; ids are configurable per card type and default to `F-{number}`, `J-{number}`, `B-{number}` using the next available number across the folder and subfolders.\n- Project load reads root markdown headers first for active cards, then reads subfolder headers in the background for search/history data. Header parsing and active/background splitting go through the shared parsing service.\n- Auto-save file edits, but batch commits so normal typing commits at most every 30 seconds; force a final commit on close.\n- Support auto-push and manual-push modes. Manual mode exposes a push command in the menu.\n- Auto-load the last project on app start and allow branch switching from the menu.\n- When external markdown files are discovered, import files that do not follow naming conventions as new features; headers are optional.\n\n## acceptance criteria\n- A project can be created or opened from GitHub by selecting repository and branch, and from Electron by selecting a local `.git` folder.\n- The configured working folder is loaded from the project; missing folders trigger folder selection or template-based creation.\n- Branch switching reloads project content from the selected branch.\n- New cards are created, committed and named with the configured id and `{id}-{title}.md` convention.\n- Root markdown headers populate active cards before background subfolder header loading begins.\n- Auto-save persists edits, delayed commits are limited to roughly every 30 seconds during editing, and closing forces any pending commit.\n- Auto-push pushes committed changes automatically; manual-push mode leaves commits unpushed until the user runs the push command.\n- External file additions, removals and changes are reflected in the app when using the Electron local Git service.\n\n## see also\n- `design\\architecture\\initial description\\data management.md`\n- `design\\architecture\\initial description\\overview.md`\n- `design\\architecture\\initial description\\desktop app.md`\n- `design\\architecture\\parsing_service.md`\n\r\ndesign\\feature_descriptions\\F_004_app_layout.md\r\n---\nid: F-004\ntitle: app layout\nstatus: ready\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: 21a12220-2d7a-4e6b-a775-a289a13c6188\n---\n\n## Goal\nBuild the app entry point and main window: service startup, theme loading, main toolbar (collapsing to hamburger on mobile), left/right panels with splitter, status bar, keyboard status and running-agents indicator, optimized for both desktop and mobile.\n\n## Current state\nA React app (MUI) exists with GitHub authentication (`GithubAuthPanel`, `useGithubAuth`) and a basic `ProjectWorkspace` rendered inside a centered container in `App.tsx`. There is no application shell yet: no main window, no light/dark theme switching (only `CssBaseline`), no main toolbar, no left/right panels with splitter, no status bar and no keyboard/running-agents indicators.\n\n## implementation details\n- Add an app entry point that starts services and loads data before showing the main window; reuse the existing auth and project bootstrap.\n- Load and manage a light/dark theme via an MUI `ThemeProvider`; persist the user's choice and expose a toggle from the toolbar.\n- Add a main window that owns the global layout and switches between desktop and mobile presentations using MUI breakpoints.\n- Add a main toolbar at the top; on mobile it collapses into a hamburger button that opens the left-panel content (tree or column names).\n- Body uses a left panel and right panel separated by a draggable splitter on desktop; on mobile the left panel moves into the hamburger menu and the body fills the width.\n- Add a status bar (desktop) showing editable info, keyboard status (caps lock, insert) and a running-agents count with a popup listing the running agents.\n- Depend on data management ([[F-002]]) for project/card content; this feature only provides the shell and hosts card/tree/editor views.\n\n## acceptance criteria\n- The app starts services and loads the last project before the main window is shown.\n- Light and dark themes can be toggled from the toolbar and the choice is remembered across restarts.\n- On desktop the body shows a left and right panel with a working splitter; on mobile the left panel is reachable from the hamburger menu and the body is full width.\n- The main toolbar is shown on desktop and collapses to a hamburger button on mobile.\n- The status bar (desktop) shows info, keyboard status (caps lock, insert) and the number of running agents, with a popup listing them.\n- The layout adapts correctly between desktop and mobile at the configured breakpoints.\n\n## see also\n- `design\\architecture\\initial description\\app layout.md`\n- `design\\architecture\\initial description\\overview.md`\n\r\ndesign\\feature_descriptions\\F_001_github_authentication.md\r\n---\nid: F-001\ntitle: github authentication\nstatus: ready\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: 29eeeca9-280a-4ce3-b549-de0fc02001d6\n---\n\n> **UPDATE 2026-07-11 â€” device-flow / OAuth login removed.** Auth is now personal-access-token only (see [[F_035_github_pat_fallback]]); the OAuth CORS proxy was dropped (see [[F_034_github_oauth_cors_proxy]]). Any device-flow, `client_id`, scopes, or OAuth-proxy detail below is historical.\n\n## Goal\nAllow the user to log in with GitHub credentials so the app can read and write markdown files stored in a GitHub repository.\n\n## Current state\nNot implemented. No auth exists yet; the app skeleton (J-001) has no login, no GitHub client, and no token storage. This feature is a prerequisite for the GitHub storage service in [F-002](F_002_data_management.md).\n\n## implementation details\nUse the **GitHub OAuth Device Flow** (no client secret, works for a static client-only SPA):\n\n- Register a GitHub OAuth app; its `client_id` ships in the app config. Request scopes needed to read/write repo contents (`repo`, or fine-grained contents read/write).\n- Login flow: request a device + user code, show the user code and the `verification_uri` (with a \"copy code / open GitHub\" button), then poll the token endpoint until the user authorizes (respect `interval` and `slow_down`; handle `authorization_pending`, `expired_token`, `access_denied`).\n- **CORS caveat:** GitHub's device/token endpoints do not send browser CORS headers. Route these two calls through the Electron bridge when connected; for the standalone web app, route them through a minimal CORS-passthrough (config-driven URL). No secret is involved, so this stays backend-free.\n- Store the resulting access token in an auth service (single source of truth). Persist it (e.g. `localStorage`) so login survives reload; auto-load on start for the \"auto-load last project\" behaviour.\n- Expose `login()`, `logout()` (clear token), current-user info, and `isAuthenticated`. All GitHub API/storage calls read the token from this service.\n- Handle token failures centrally: a `401` clears the token and returns the user to the login screen.\n- Electron/local-Git mode does **not** use this flow (it works on the local filesystem/git); GitHub auth is only required for the GitHub storage backend.\n\n## acceptance criteria\n- An unauthenticated user is shown a \"Sign in with GitHub\" action; completing the device flow leaves the app authenticated.\n- The device flow shows the user code + verification URL, polls correctly, and surfaces pending / denied / expired states without hanging.\n- After a successful login the token is persisted and automatically restored on the next app start (no re-login needed until it is revoked/expires).\n- Authenticated GitHub API calls succeed using the stored token; the user's login/identity is available to the UI.\n- `logout()` clears the stored token and returns the app to the signed-out state.\n- A `401` from GitHub clears the token and routes the user back to sign-in.\n\n## see also\n- `design\\architecture\\initial description\\overview.md`\n- `design\\architecture\\initial description\\data management.md`\n\r\ndesign\\feature_descriptions\\F_006_text_view.md\r\n---\nid: F-006\ntitle: text view\nstatus: ready\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: a66239e5-a985-4ff4-bd9c-388c2b767aed\n---\n\n## Goal\nImplement the text view: a folder/status tree on the left (including special folders) and tabbed open files on the right, with mobile behavior that moves the tree into the hamburger menu.\n\n## Current state\nThe app shell ([[F-004]]) provides a desktop splitter and mobile hamburger drawer, but the left panel still hosts `GithubAuthPanel` instead of the text tree. `ProjectWorkspace` now renders active cards through the kanban `CardView` ([[F-005]]) with status columns, drag-to-move and inline title/policy edits. It already carries a `viewMode` toggle of `'cards' | 'file'`, but the `'file'` mode is only a stopgap: it shows the single `selectedCard` in a plain multiline `TextField` with a \"Back to cards\" button â€” there is no folder/status tree, no tabbed multi-file surface, and no route or mode switch dedicated to a text view. Card splitting now runs through the shared `markdownParsingService` ([[F-021]]). `DataService` loads markdown files recursively from the working folder and exposes `ProjectSnapshot` (active cards, background cards, working folder) plus save/commit via `saveFile`, but it does not expose a tree model, open-file/tab state or special-folder metadata.\n\n## implementation details\n- Add a text-view mode hosted by `ProjectWorkspace` or a dedicated child component, keeping project open/create and branch/push controls available.\n- Build a tree model from the loaded markdown files: real folders, special folders from [[F-003]], and status groupings for active cards.\n- Selecting a file opens it in the right pane as a tab; selecting an already-open file activates its existing tab.\n- switching tabs selects the file in the tree on the left pane.\n- Tabs show the file title/id when available and support close/activate behavior without losing unsaved auto-save behavior from `DataService.saveFile`.\n- Reuse the markdown editor surface from [[F-007]] when available; until then the text view can keep the existing textarea editing path.\n- On desktop, show the tree in the left split panel and tabs/editor in the right panel. On mobile, move the tree into the hamburger drawer and keep the active tab/editor full width.\n- Preserve loading behavior: root cards stay available first, while subfolder/special-folder files appear when background cards are loaded.\n\n## acceptance criteria\n- Opening a project shows a text view with a navigable tree containing folders, markdown files, special folders and status groups.\n- Clicking a markdown file opens it in a tab; clicking it again focuses the existing tab instead of duplicating it.\n- Multiple files can be open, switched between and closed from the tab bar.\n- Editing the active tab persists through the existing data service save/commit flow.\n- Desktop layout uses the left splitter panel for the tree and the right panel for tabs/editor.\n- Mobile layout puts the tree in the hamburger drawer and keeps the selected file editor full width.\n- Root files are usable before subfolder files finish loading, and subfolder/special-folder files appear without replacing active tabs.\n- Tests cover tree construction, tab open/close/focus behavior and desktop/mobile rendering.\n\n## see also\n- `design\\architecture\\initial description\\overview.md`\n- `design\\architecture\\initial description\\app layout.md`\n\r\ndesign\\feature_descriptions\\F_003_special_folders.md\r\n---\nid: F-003\ntitle: special folders\nstatus: design\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: 1c06d955-309d-4d0f-80ff-6284afbbb395\nafter: 964fdcac-159c-49dc-af83-79f532e9651d\n---\n\n## Goal\nSupport the special folders in a project (history with a sub folder per release, architecture, prompts/actions), including moving md files to a history sub folder when a release is done and background loading of sub folder headers for search.\n\n## Current state\nOnly the design notes exist. There is no project structure, folder handling, release/history logic or background header loading implemented yet.\n\n## implementation details\n- Recognize special folders inside the working folder: `history`, `architecture` and `prompts` (actions). Names should be configurable, defaulting to these.\n- `history` holds one subfolder per release; active (root) cards are moved into the release subfolder when a release is completed.\n- `architecture` holds generic description markdown files (like `data management.md`).\n- `prompts` holds the actions that can run on markdown files; each action is defined by a markdown header (name, when allowed, ...) and/or a json definition that may reference a prompt file.\n- Root markdown headers are loaded first for active cards; special/subfolder headers are loaded afterwards in the background and made available to search.\n- \"Complete release\" operation moves the current root cards into a new `history/{release}` subfolder and commits the moves.\n- Id numbering considers files across the folder and its subfolders (including history) so ids stay unique after archiving.\n\n## acceptance criteria\n- The `history`, `architecture` and `prompts` folders are recognized when a project is loaded, using configured or default names.\n- Completing a release creates a `history/{release}` subfolder and moves the active root cards into it.\n- Architecture files are loaded and available as generic description cards.\n- Prompt/action files are loaded from the `prompts` folder using their header/json definition.\n- Subfolder headers are loaded in the background after the root loads and are searchable.\n- New card ids remain unique against files in subfolders, including archived history cards.\n\n## see also\n- `design\\architecture\\initial description\\data management.md`\n\r\ndesign\\feature_descriptions\\F_007_markdown_editor.md\r\n---\nid: F-007\ntitle: markdown editor\nstatus: ready\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: 55bf4053-034f-411d-9c02-a790eac475ce\n---\n\n## Goal\nIntegrate MDXEditor (with plugins for lists, quotes, tables, code blocks, links and images) as the editor for card bodies and files, with a local formatting toolbar that stays sticky at the top on mobile.\n\n## Current state\n`@mdxeditor/editor` is installed but still not used by any component in `app/src`; every editing surface is an interim multiline MUI `TextField`. Card view ([[F-005]]) and text view ([[F-006]]) are both implemented and wired through `ProjectWorkspace`, so `ProjectWorkspace` no longer edits a card directly â€” it delegates to `CardView` and `TextView` and forwards their changes to `DataService`. Card body editing goes through `CardBodyEditor` (used by the desktop `CardBodyDialog` and mobile accordion), whose `onBodyChange` calls `DataService.updateCardBody`; that method already uses the shared `markdownParsingService.replaceBody` to preserve the frontmatter/header block and replace only the body. Text view edits full file content in a per-tab `TextField` and saves via the same `onBodyChange`/`DataService` path. Both `CardBodyEditor` and the text-view editor carry TODO notes that the MDXEditor component and its formatting toolbar land with F-007 and replace them. There is still no shared editor component and no formatting toolbar (sticky or otherwise).\n\n## implementation details\n- Create a reusable markdown editor component in the app and use MDXEditor with plugins for lists, quotes, tables, thematic breaks, code blocks, links and images.\n- Keep persistence unchanged: editor changes produce markdown text and callers save via `DataService.saveFile` with the existing `{ path, sha, content }` contract.\n- Support both full-file editing for text view ([[F-006]]) and body editing for card view ([[F-005]]); body editing must use the shared parsing service to preserve the existing frontmatter/header block and replace only the markdown body.\n- Replace the current `ProjectWorkspace` textarea path with the shared editor, then reuse the same component in card dialog/mobile accordion and future file tabs.\n- Add a local formatting toolbar attached to the editor; on mobile it stays sticky at the top of the scrollable editor/card body area.\n- Handle empty files, header-only files, invalid markdown constructs accepted by plain text, and rapid edits without losing the existing debounced commit behavior.\n- Import MDXEditor styles in the app entry/component path and keep layout consistent with the current MUI shell.\n\n## acceptance criteria\n- The selected markdown card/file is edited with MDXEditor instead of a textarea.\n- Toolbar actions support lists, quotes, tables, code blocks, links and images.\n- Editing persists through the existing `DataService.saveFile` and commit/push flow.\n- Card body editing preserves the markdown header/frontmatter through the shared parsing service and updates only the body.\n- The same editor component can be used by card view and text view without duplicating persistence logic.\n- On mobile, the formatting toolbar remains sticky above the editor content while scrolling.\n- Tests cover editor rendering, change propagation to `saveFile`, body-only updates with header preservation, and mobile sticky-toolbar layout state.\n\n## see also\n- `design\\architecture\\initial description\\components.md`\n- `design\\architecture\\initial description\\app layout.md`\n- `design\\architecture\\initial description\\overview.md`\n- `design\\architecture\\parsing_service.md`\n\r\ndesign\\feature_descriptions\\F_005_card_view.md\r\n---\nid: F-005\ntitle: card view\nstatus: ready\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: 6c90adc8-e294-4377-b9f9-7eabe2fc362b\n---\n\n## Goal\nShow markdown files as status columns with draggable, ordered cards. Cards expose type color, `id`, title, policy leds, inline title editing, body access, and a switch to file mode.\n\n## Current state\nParsing now lives behind the shared `markdownParsingService` ([[F-021]]), whose `parseCard`/`splitCards` create `ProjectCard`s that `DataService` can save. `CardTypeConfig` already carries a per-type `color` (added with theming, [[F-018]]). `CardHeader` has `id`, `title`, `status`, `owner`, `affects` and `internalId`, but not parsed `after` ordering or `policy`. `ProjectWorkspace` still shows active cards as a flat `CardSelectButton` list with a plain `TextField` textarea editor â€” no columns, drag-and-drop, policy leds, type-color line, inline title editing, or body dialog/accordion. No drag-and-drop library is installed.\n\n## Implementation\n- Data model: parse `after` and `policy` in the shared parsing service, add them to `CardHeader`, and keep `internalId` as the stable identity referenced by `after`. Extend `CardTypeConfig` with a per-type color.\n- Layout: host the view in the app shell ([[F-004]]), optimized for desktop and mobile. Render one column per distinct `status`; column title is the status, and each card appears in its matching column.\n- Card chrome: show a vertical type-color line before the card, then `id`, title, and upper-right policy leds. Clicking a policy led toggles that policy and persists through `DataService.saveFile`.\n- Ordering: derive column order from `after`, where `after` stores the preceding card's `internalId`. Dragging within a column updates `after`; dragging between columns updates `status` and `after`. Use `@dnd-kit` (`@dnd-kit/core` + `@dnd-kit/sortable`, with `@dnd-kit/modifiers` as needed) for drag-and-drop â€” chosen for built-in touch/pointer support (desktop + mobile), a sortable model that fits cross-column moves, and its lightweight, TypeScript-native, accessible API. On drop, persist only the two/three cards whose `after` values changed.\n- Editing/navigation: double-click or edit affordance enables inline title editing, updates `header.title`, and saves. Clicking a card opens the markdown body in a desktop dialog or expands it inline as a mobile accordion; body editing and toolbar behavior come from the markdown editor ([[F-007]]). A card/dialog action switches to file mode ([[F-006]]) with that card open.\n\n## Acceptance Criteria\n- Cards are grouped into columns by `status`, one column per distinct status value.\n- Each card shows its type color line, `id` before the title, the title, and policy leds; clicking a led toggles the policy and persists the change.\n- Dragging a card to another column changes its `status`; dragging within a column reorders it, and only the affected cards' `after` values are written.\n- Card order is derived from the `after` tag and survives reload.\n- The title can be edited inline and is persisted.\n- On desktop, clicking a card opens its body in a dialog; on mobile, the card expands as an accordion with the body inline.\n- A card action switches to file mode with that card open.\n- The view works on both desktop and mobile.\n\n## See Also\n- `design\\architecture\\initial description\\overview.md`\n- `design\\architecture\\initial description\\app layout.md`\n- `design\\architecture\\parsing_service.md`\n\r\ndesign\\feature_descriptions\\F_008_templates_and_headers.md\r\n---\nid: F-008\ntitle: templates and headers\nstatus: ready\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: 0fa47bfc-3180-42d5-a1c5-539cf572e470\n---\n\n## Goal\nApply a template when a new markdown file is created and automatically add the specially formatted header (`author`, `id`, `internalId`, `title`, `status`, `owner`, `affects`, `policy`); import files that don't follow the naming convention as new features.\n\n## Current state\nNew cards are created through `DataService.createCard` and `createCardFile`. File naming uses the configured card type prefix and next available number, and generated markdown now goes through `markdownParsingService.buildCardMarkdown`. The generated header includes `id`, `internalId`, `title`, `status: new` and `affects`, followed by a title heading and the body entered in the new-card form. There is no configured body template yet, and new-card generation still does not write `author`, `owner` or `policy`.\n\nMarkdown parsing and serialization now live in `app/src/services/markdown_parsing_service.ts` ([[F-021]]). `DataService` uses it to split active/background cards, parse loaded files, replace card bodies while preserving headers, rewrite header fields, toggle policy flags and refresh snapshots after saves. `CardHeader` currently contains `id`, `internalId`, `title`, `status`, `owner`, `affects`, `after` and `policy`; it does not contain `author`. Generic parsing can read scalar, list and nested-map frontmatter fields, while card parsing imports files outside the `{id}-{title}.md` convention as status `new` and falls back to body/title data when headers are missing or malformed.\n\n## implementation details\n- Extend `CardHeader` and the shared parsing service to parse the full supported header: `author`, `id`, `internalId`, `title`, `status`, `owner`, `affects` and `policy`.\n- Keep headers optional for imported/external files; files without naming convention remain imported as new feature cards.\n- Replace the hardcoded card markdown builder with parsing-service markdown generation used by new card creation.\n- Generate `internalId` once when a card is created and preserve it on later edits.\n- Keep id generation and file naming in `card_naming.ts`: use the configured card type prefix and next available number across working folder and subfolders.\n- Keep project workspace template creation separate: missing working folders still get the README workspace template.\n\n## acceptance criteria\n- Creating a new card writes a markdown file named `{id}-{title}.md` in the configured working folder.\n- The new file contains the configured body template and a frontmatter header with `author`, `id`, `internalId`, `title`, `status`, `owner`, `affects` and `policy`.\n- `internalId` is generated once per new card and is not derived from the filename or display id.\n- Loading existing markdown parses the supported header fields into `CardHeader` through the shared parsing service.\n- Loading markdown without a header still creates a card from body/title fallback data.\n- Loading root markdown files that do not follow the naming convention imports them as new feature cards.\n- Tests cover parsing-service header parsing, full-header card creation, generated `internalId`, and import behavior for non-convention files.\n\n## see also\n- `design\\architecture\\initial description\\overview.md`\n- `design\\architecture\\initial description\\data management.md`\n- `design\\architecture\\parsing_service.md`\n\r\ndesign\\feature_descriptions\\F_010_actions.md\r\n---\nid: F-010\ntitle: actions\nstatus: design\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: d6d1a8c0-c193-4f2c-b3ec-2e9a31c0c444\nafter: 1c06d955-309d-4d0f-80ff-6284afbbb395\n---\n\n> **Split for implementation.** Implement the ordered sub-features instead of this umbrella feature.\n> - [[F-010a]] action model and loading - stable ids, model, loader, validation, circular-call check, service and hook\n> - [[F-010b]] action entry points and popup - `appliesTo`, entry points, popup, run/cancel controls, related-action links\n> - [[F-010c]] Electron action execution and chaining - Electron runner, placeholders, `onBefore`/main/`on`/`onAfter`, logs and status\n> - [[F-010d]] agent actions - agent flow, extra prompt, conversation input, run history and `convert to action`\n> - [[F-010e]] state triggers and folder watching - `onState`, card current-action state and hot reload\n>\n> Dependency order is a -> b -> c -> d/e. D and E both build on C.\n\n## Goal\n\nLoad ID-based JSON action definitions from the project's actions folder, show context-sensitive action entry points, and execute actions only through an Electron-side action runner. Support agent and command actions, the built-in custom-prompt action, placeholders, `onBefore`/`on`/`onAfter` chaining, `onState`, `needsWorkTree`, cancellation, and `appliesTo`.\n\n## Current state\n\nThe existing implementation uses a React-side `ActionRunner`, name-based action lookup, `agent | cmd`, `text`, `before`/`after`, inline/by-name references, and a separate Electron scheduled-action runner. The implementation must move orchestration to Electron and migrate to the canonical model below without legacy-shape fallback.\n\n## implementation details\n\n- Define actions with required stable `id`, editable `name`, `label`, `description`, and `type` (`agent` | `command`). Agent actions require `prompt`; command actions require `command`.\n- Add optional `icon`, `appliesTo`, `onBefore`, `on`, `onAfter`, `onState`, `needsWorkTree`, `agent`, `model`, and `thinkingLevel`.\n- Persist `onBefore` and `onAfter` as ordered action `id` lists. Persist `on` as ordered `{ condition, actionId }` entries. Do not support inline linked definitions or name-based references.\n- Register a built-in `custom prompt` agent action with its own stable reserved `id`, independent of project files.\n- Load actions when a project opens. Fail fast on invalid JSON, missing fields, duplicate ids, unknown action ids, invalid regular expressions, or circular calls.\n- Keep the loaded definitions in the action service for editing, display, filtering, and search. React does not orchestrate or execute them.\n- Show compact entry points near matching cards, files, and folders based on `appliesTo`.\n- Open a resizable popup for the selected action id and context. Show `Run`, `Cancel` while running, and a `Schedule` entry point that delegates to [[F-022]].\n- For agent actions, show extra prompt input and the supported per-run agent/model/thinking-level choices. Model choices come from configured profiles with built-in defaults; thinking choices are `none`, `low`, `medium`, `high`, and `max`.\n- The renderer sends only `{ actionId, context, runInput }`. Electron reloads and validates the persisted definition by `id`, resolves placeholders, and executes the complete chain.\n- Execute `onBefore` -> main -> matching `on` actions -> `onAfter` in configured order. Reject cycles before execution.\n- Stop the chain on the first failure. `onBefore` failure prevents main. Main failure prevents `on` and `onAfter`. A matched-`on` failure prevents remaining `on` and all `onAfter`. `onAfter` starts only after main and every matched `on` succeed; its failure stops later `onAfter`, fails that linked action, and finishes the selected run as `okButNotAfter`.\n- `Cancel` stops the active Electron process and remaining chain and marks the run cancelled.\n- When `needsWorkTree` is set, Electron requires card context and resolves the card's valid assignment from Git's linked-worktree list. It does not create a worktree or automatically commit, push, merge, cherry-pick, or transfer changes.\n- A card keeps its current action in memory. While set, all action entry points for that card are disabled. Completion, failure, or cancellation clears it and publishes an event; it is never persisted.\n- Trigger `onState` actions through the same Electron runner.\n- Watch the actions folder in local Electron mode and publish validated definition changes to React.\n\n## acceptance criteria\n\n- Opening a project loads valid ID-based action JSON and exposes it to React.\n- Legacy `cmd`/`text`/`before`/`after`/name-reference and inline-reference shapes are rejected rather than normalized.\n- Invalid definitions report the source and do not replace the previous valid action set.\n- Actions appear only in contexts matching `appliesTo`; the built-in custom-prompt action remains available in supported contexts.\n- Activating an entry point opens a resizable popup bound to the action id and context.\n- React cannot execute or orchestrate an action. Manual, state-triggered, and scheduled runs use the same Electron-side action runner.\n- Command and agent definitions are resolved by id in Electron; renaming an action does not break links, schedules, or execution.\n- `onBefore`, main, `on`, and `onAfter` ordering and failure results follow this specification.\n- A running action can be cancelled and reports running, completed, failed, cancelled, or `okButNotAfter` clearly.\n- A card with a current action disables every action entry point until Electron reports a terminal state.\n- `needsWorkTree` uses a valid card-assigned worktree, rejects missing or invalid assignments and non-card contexts, and performs no implicit creation or integration operations.\n- Adding, editing, or removing local definitions updates the UI without restarting.\n\n## see also\n\n- `design\\architecture\\initial description\\actions.md`\n- `design\\architecture\\initial description\\action_popup.md`\n- `design\\architecture\\initial description\\writings\\running_actions.md`\n- `design\\architecture\\initial description\\writings\\action_editor.md`\n- `design\\feature_descriptions\\ready\\F_022_scheduled_actions.md`\n\r\n",
